// =========================================================================
// GESTÃO DE ESTÁDIO: ALUGUEL, SHOWS CULTURAIS, MANUTENÇÃO & GRAMADO
// =========================================================================

function generateStadiumRentalProposal(force = false){
  if(state.stadiumClubRental && !force) return state.stadiumClubRental;
  if(state.lastStadiumEvent?.date === state.date) return null;
  const currentClubNorm = norm(state.club || '');
  const candidates = (state.teams || [])
    .filter(t => norm(t.name) !== currentClubNorm)
    .map(t => t.name);

  const fallbackClubs = ['Ferroviária', 'Ituano', 'Botafogo-SP', 'São Bento', 'Novorizontino', 'Ponte Preta', 'Guarani', 'Mirassol', 'Londrina', 'Operário-PR'];
  const pool = candidates.length > 0 ? candidates : fallbackClubs;
  const randomClub = pool[Math.floor(Math.random() * pool.length)] || 'Ituano';

  const cap = Math.min(48000, Math.max(0, Number(state.infrastructure?.stadium?.capacity) || 8000));
  const feeFactor = 0.9 + Math.random() * 0.2;
  const baseFee = Math.round(Math.max(25000, cap * (3.5 + Math.random() * 2) * feeFactor));

  state.stadiumClubRental = {
    club: randomClub,
    fee: baseFee,
    wear: 6,
    receivedRound: Number(state.round) || 0,
    expiresAfterRound: (Number(state.round) || 0) + 3,
    receivedDate: state.date
  };
  return state.stadiumClubRental;
}

function addNews(txt){
  if(!txt || !state) return;
  if(!Array.isArray(state.news)) state.news = [];
  state.news.unshift(txt);
  if(state.news.length > 50) state.news = state.news.slice(0, 50);
}
window.addNews = addNews;

function acceptClubRental(returnToCentral = false){
  if(!state.stadiumClubRental) return;
  const r = state.stadiumClubRental;
  const fee = Number(r.fee);
  if(!Number.isFinite(fee) || fee <= 0){ toast('Proposta de aluguel inválida.'); return; }
  state.balance = (Number(state.balance) || 0) + fee;
  state.income = (Number(state.income) || 0) + fee;
  state.stadiumMaintenance = Math.max(10, (state.stadiumMaintenance || 90) - (r.wear || 6));
  state.lastStadiumEvent = { type: 'rental', name: r.club, fee, date: state.date, wear: r.wear || 6 };
  toast(`🤝 Aluguel confirmado com o ${r.club}! +${fmtMoney(r.fee)} creditados no caixa.`);
  addNews(`Estádio alugado para o ${r.club} por ${fmtMoney(r.fee)}. Desgaste da partida: -${r.wear || 6}%.`);
  state.stadiumClubRental = null;
  state.pendingDecision = null;
  save();
  if(!returnToCentral) openStadiumModal();
  else render();
}

function expireStadiumEventConfirmation(){
  if(state?.lastStadiumEvent?.date && state.lastStadiumEvent.date < state.date){
    state.lastStadiumEvent = null;
    return true;
  }
  return false;
}

function rejectClubRental(returnToCentral = false){
  if(!state.stadiumClubRental) return;
  toast('Proposta de aluguel recusada.');
  state.stadiumClubRental = null;
  save();
  if(!returnToCentral) openStadiumModal();
  else render();
}

function generateStadiumEventProposal(force = false){
  if(state.stadiumEventProposal && !force) return state.stadiumEventProposal;
  if(state.lastStadiumEvent?.date === state.date) return null;
  const events = [
    { name: '🎤 Turnê Tardezinha (Thiaguinho)', mult: 1.4 },
    { name: '🔥 Show Numanice (Ludmilla)', mult: 1.5 },
    { name: '🤠 Festival Sertanejo Villa Mix', mult: 1.3 },
    { name: '🎸 Turnê Rock Brasil Festival', mult: 1.2 },
    { name: '🌟 Turnê Pop Mega Estádio', mult: 1.35 },
    { name: '🎧 Festival Eletrônico Só Track Boa', mult: 1.25 }
  ];
  const chosen = events[Math.floor(Math.random() * events.length)];
  const cap = state.infrastructure?.stadium?.capacity || 8000;
  const stadLvl = Number(state.infrastructure?.stadium?.level) || 1;
  const eventLvlMult = 1 + (stadLvl - 1) * 0.40;
  const baseFee = Math.max(120000, Math.round(cap * (20 + Math.random() * 15) * chosen.mult * eventLvlMult));

  state.stadiumEventProposal = {
    name: chosen.name,
    fee: baseFee,
    receivedRound: Number(state.round) || 0,
    expiresAfterRound: (Number(state.round) || 0) + 3,
    receivedDate: state.date
  };
  return state.stadiumEventProposal;
}

// Offers stay actionable through two complete rounds after being received.
// Legacy metadata is migrated once and then persisted by the normal save routine.
function expireRoundLimitedOffers(currentRound = Number(state?.round) || 0){
  if(!state) return { expiredBids:0, expiredRental:false, expiredShow:false };
  let expiredBids = 0, expiredRental = false, expiredShow = false;
  const round = Number(currentRound) || 0;
  const migrateOffer = offer => {
    if(!offer || typeof offer !== 'object') return;
    const receivedIsKnown = offer.receivedRound !== undefined && offer.receivedRound !== null && Number.isFinite(Number(offer.receivedRound));
    if(!receivedIsKnown){
      offer.receivedRound = round;
      offer.expiresAfterRound = round + 3;
      offer.expiryMetadataMigrated = true;
      return;
    }
    offer.receivedRound = Number(offer.receivedRound);
    const expiryIsKnown = offer.expiresAfterRound !== undefined && offer.expiresAfterRound !== null && Number.isFinite(Number(offer.expiresAfterRound));
    offer.expiresAfterRound = expiryIsKnown ? Number(offer.expiresAfterRound) : offer.receivedRound + 3;
  };
  state.incomingBids = Array.isArray(state.incomingBids) ? state.incomingBids : [];
  state.incomingBids = state.incomingBids.filter(bid => {
    migrateOffer(bid);
    if(round > bid.expiresAfterRound){ expiredBids++; return false; }
    return true;
  });
  if(state.stadiumClubRental){
    const offer = state.stadiumClubRental;
    migrateOffer(offer);
    if(round > offer.expiresAfterRound){ state.stadiumClubRental = null; expiredRental = true; }
  }
  if(state.stadiumEventProposal){
    const offer = state.stadiumEventProposal;
    migrateOffer(offer);
    if(round > offer.expiresAfterRound){
      const eventName = offer.name;
      state.stadiumEventProposal = null;
      state.news = (state.news || []).filter(item => !(String(item).includes(eventName) && (String(item).includes('CONVITE PARA EVENTO:') || String(item).includes('PROPOSTA DE EVENTO:'))));
      expiredShow = true;
    }
  }
  if(expiredBids || expiredRental || expiredShow){
    state.news = Array.isArray(state.news) ? state.news : [];
    if(expiredBids) state.news.unshift(`⏰ ${expiredBids} proposta(s) milionária(s) expiraram após duas rodadas sem resposta. A oportunidade foi perdida.`);
    if(expiredRental) state.news.unshift('⏰ A proposta de aluguel do estádio expirou após duas rodadas sem resposta.');
    if(expiredShow) state.news.unshift('⏰ O convite para show no estádio expirou após duas rodadas sem resposta.');
    state.news = state.news.slice(0, 50);
    if(typeof save === 'function') save();
    if(typeof renderHomeBidsBanner === 'function') renderHomeBidsBanner();
    if(typeof render === 'function' && typeof document !== 'undefined' && document.getElementById('alertPendingDecisionBadge')) render();
  }
  return { expiredBids, expiredRental, expiredShow };
}

function acceptEventConcert(returnToCentral = false){
  if(!state.stadiumEventProposal) return;
  const ev = state.stadiumEventProposal;
  const fee = Number(ev.fee);
  if(!Number.isFinite(fee) || fee <= 0){ toast('Proposta de show inválida.'); return; }
  state.balance = (Number(state.balance) || 0) + fee;
  state.income = (Number(state.income) || 0) + fee;
  const wear = state.stadiumPitchType === 'synthetic' ? 4 : 18;
  state.stadiumMaintenance = Math.max(10, (state.stadiumMaintenance || 90) - wear);
  state.lastStadiumEvent = { type: 'concert', name: ev.name, fee, date: state.date };
  state.news = (state.news || []).filter(item => !(String(item).includes(ev.name) && (String(item).includes('CONVITE PARA EVENTO:') || String(item).includes('PROPOSTA DE EVENTO:'))));
  toast(`🎉 ${ev.name} autorizado! +${fmtMoney(fee)} arrecadados com aluguel do estádio!`);
  addNews(`Megaevento realizado no estádio: ${ev.name}. Renda líquida extraordinária de ${fmtMoney(fee)}.`);
  state.stadiumEventProposal = null;
  state.pendingDecision = null;
  save();
  if(!returnToCentral) openStadiumModal();
  else render();
}

function rejectEventConcert(returnToCentral = false){
  if(!state.stadiumEventProposal) return;
  const eventName = state.stadiumEventProposal.name;
  toast('Convite para show cultural recusado.');
  state.news = (state.news || []).filter(item => !(String(item).includes(eventName) && (String(item).includes('CONVITE PARA EVENTO:') || String(item).includes('PROPOSTA DE EVENTO:'))));
  state.stadiumEventProposal = null;
  save();
  if(!returnToCentral) openStadiumModal();
  else render();
}

function repairStadium(mode){
  const cost = mode === 'quick' ? 25000 : 75000;
  if((state.balance || 0) < cost){
    toast('Saldo insuficiente no caixa para realizar reparos no estádio!');
    return;
  }
  state.balance -= cost;
  state.expense = (state.expense || 0) + cost;
  const curM = state.stadiumMaintenance || 80;
  state.stadiumMaintenance = mode === 'quick' ? Math.min(100, curM + 25) : 100;
  toast(`🔧 Manutenção concluída! Conservação do estádio em ${state.stadiumMaintenance}%.`);
  save();
  openStadiumModal();
}

function installPitchType(ptype){
  const cost = ptype === 'synthetic' ? 220000 : ptype === 'hybrid' ? 150000 : 0;
  if(cost > 0 && (state.balance || 0) < cost){
    toast('Saldo insuficiente para trocar o tipo de gramado!');
    return;
  }
  if(cost > 0){
    state.balance -= cost;
    state.expense = (state.expense || 0) + cost;
  }
  state.stadiumPitchType = ptype;
  toast(`🌱 Novo gramado instalado com sucesso: ${ptype === 'synthetic' ? 'Grama Sintética' : ptype === 'hybrid' ? 'Grama Híbrida' : 'Grama Natural'}!`);
  save();
  openStadiumModal();
}

