function getStadiumExpansionData(){
  if(!state.stadiumRingData){
    state.stadiumRingData = {
      ring: Math.max(1, Math.min(6, Number(state.infrastructure?.stadium?.level) || 1)),
      maxRings: 6,
      sides: { norte: false, sul: false, leste: false, oeste: false },
      rings: {
        1: { norte: false, sul: false, leste: false, oeste: false },
        2: { norte: false, sul: false, leste: false, oeste: false },
        3: { norte: false, sul: false, leste: false, oeste: false },
        4: { norte: false, sul: false, leste: false, oeste: false },
        5: { norte: false, sul: false, leste: false, oeste: false },
        6: { norte: false, sul: false, leste: false, oeste: false }
      },
      purchasedSectors: [],
      activeWork: null,
      debt: { remaining: 0, monthly: 0, monthsLeft: 0 },
      closedSeats: 0
    };
  }

  const st = state.stadiumRingData;
  st.maxRings = 6;
  st.ring = Math.max(1, Math.min(st.maxRings, Number(st.ring) || 1));
  st.maxUnlockedRing = Math.max(st.ring, Math.min(st.maxRings, Number(st.maxUnlockedRing) || Number(state.infrastructure?.stadium?.level) || 1));
  st.rings = st.rings || {};
  for(let r = 1; r <= 6; r++){
    st.rings[r] = st.rings[r] || { norte: false, sul: false, leste: false, oeste: false };
    ['norte', 'sul', 'leste', 'oeste'].forEach(side => { st.rings[r][side] = st.rings[r][side] === true; });
  }
  st.purchasedSectors = Array.isArray(st.purchasedSectors) ? st.purchasedSectors : [];

  // Migração transparente de saves legados que só tinham st.sides
  if(st.sides && st.ring === 1 && (!st.purchasedSectors || st.purchasedSectors.length === 0)){
    ['norte', 'sul', 'leste', 'oeste'].forEach(side => {
      if(st.sides[side] && !st.rings[1][side]){
        st.rings[1][side] = true;
      }
    });
  }

  // A capacidade inicial define quantos anéis já existiam. Cada anel até
  // esse nível começa completo; um nível superior nunca pode pular etapas.
  const capacity = Math.max(0, Number(state.infrastructure?.stadium?.capacity) || 0);
  const capacityRing = capacity >= 100000 ? 6
    : capacity >= 72160 ? 5
    : capacity >= 49000 ? 4
    : capacity >= 30640 ? 3
    : capacity >= 18000 ? 2
    : capacity >= 7000 ? 1 : 0;
  let contiguousCompleteRings = 0;
  for(let ring = 1; ring <= 6; ring++){
    if(['norte', 'sul', 'leste', 'oeste'].every(side => st.rings[ring][side] === true)) contiguousCompleteRings = ring;
    else break;
  }
  const completedThrough = Math.max(capacityRing, contiguousCompleteRings);
  for(let ring = 1; ring <= completedThrough; ring++){
    st.rings[ring] = { norte: true, sul: true, leste: true, oeste: true };
  }
  const stadiumSides = ['norte', 'sul', 'leste', 'oeste'];
  const hasValidActiveWork = !!st.activeWork && Number(st.activeWork.ring) >= 1 && Number(st.activeWork.ring) <= 6;
  if(hasValidActiveWork){
    const workRing = Number(st.activeWork.ring);
    if(!stadiumSides.includes(st.activeWork.side)){
      st.activeWork.side = stadiumSides.find(side => st.rings[workRing][side] !== true) || 'norte';
    }
    // Marcar a obra como pendente antes de identificar o primeiro anel incompleto.
    st.rings[workRing][st.activeWork.side] = false;
  }
  // Mantém os setores já concluídos somente no primeiro anel incompleto,
  // removendo anéis superiores que tenham sido marcados por saves antigos.
  let firstIncompleteRing = 6;
  for(let ring = 1; ring <= 6; ring++){
    const isComplete = ['norte', 'sul', 'leste', 'oeste'].every(side => st.rings[ring][side] === true);
    if(!isComplete){ firstIncompleteRing = ring; break; }
  }
  for(let ring = firstIncompleteRing + 1; ring <= 6; ring++){
    st.rings[ring] = { norte: false, sul: false, leste: false, oeste: false };
  }
  // Uma obra legada fora de sequência é migrada para o primeiro anel incompleto,
  // para que a construção termine num setor válido sem desbloquear anéis superiores.
  if(hasValidActiveWork){
    let workRing = Number(st.activeWork.ring);
    let workSide = st.activeWork.side;
    if(workRing > firstIncompleteRing){
      workRing = firstIncompleteRing;
      if(st.rings[workRing][workSide] === true){
        workSide = stadiumSides.find(side => st.rings[workRing][side] !== true) || 'norte';
      }
      st.activeWork.ring = workRing;
      st.activeWork.side = workSide;
    }
    st.rings[workRing][workSide] = false;
    st.ring = Math.max(1, Math.min(workRing, st.maxUnlockedRing));
  } else {
    st.ring = Math.max(1, Math.min(firstIncompleteRing, st.maxUnlockedRing || 6));
  }
  // Sincroniza purchasedSectors com todos os anéis
  st.purchasedSectors = st.purchasedSectors.filter(key => {
    const match = /^r([1-6])_(norte|sul|leste|oeste)$/.exec(key);
    return !!match && st.rings[Number(match[1])]?.[match[2]] === true;
  });
  for(let r = 1; r <= 6; r++){
    ['norte', 'sul', 'leste', 'oeste'].forEach(side => {
      if(st.rings[r][side]){
        const key = `r${r}_${side}`;
        if(!st.purchasedSectors.includes(key)){
          st.purchasedSectors.push(key);
        }
      }
    });
  }

  // Sincroniza st.sides com o anel atual ativo
  st.sides = st.rings[st.ring];

  return st;
}

function getStadiumSectorCost(ring = 1){
  // 2. Aumento Geral de Custos (+30%): Multiplicador de 1.30 sobre o valor base de construção
  const baseCost = ring <= 2 ? 850000 : ring <= 4 ? 1200000 : 1800000;
  return Math.round(baseCost * 1.30);
}

function getStadiumSectorWorkDays(ring = 1){
  // 3. Escalonamento Realista do Prazo de Construção (Tempo Dinâmico):
  // Anéis 1 e 2: 15 a 25 dias de obra.
  // Anéis 3 e 4: 30 a 45 dias de obra.
  // Anéis 5 e 6: 50 a 90 dias de obra (megaobras estruturais).
  if(ring <= 2) return rnd(15, 25);
  if(ring <= 4) return rnd(30, 45);
  return rnd(50, 90);
}

function getStadiumSectorWorkDaysRange(ring = 1){
  if(ring <= 2) return { min: 15, max: 25, label: '15 a 25 dias' };
  if(ring <= 4) return { min: 30, max: 45, label: '30 a 45 dias' };
  return { min: 50, max: 90, label: '50 a 90 dias' };
}

function getNewArenaData(){
  state.newArenaData = state.newArenaData || {
    underConstruction: false,
    name: 'Arena Real',
    capacity: 45000,
    yearsTotal: 3,
    yearsRemaining: 3,
    debt: null
  };
  return state.newArenaData;
}

function getMuseumData(){
  state.museumData = state.museumData || {
    level: 1,
    skipOfferUsed: false
  };
  const curLvlObj = MUSEUM_LEVELS.find(m => m.level === state.museumData.level) || MUSEUM_LEVELS[0];
  
  // Taças do clube (históricas + da carreira)
  const historicalTitles = ['Campeonato Candango (2018)', 'Campeonato Candango (2019)'];
  const careerTitles = (state.titles || []).map(t => `${t} (${state.season})`);
  const allTitles = [...historicalTitles, ...careerTitles];
  const inVitrine = allTitles.slice(0, curLvlObj.capacity);
  const overflow = allTitles.slice(curLvlObj.capacity);

  return {
    levelObj: curLvlObj,
    allTitles,
    inVitrine,
    overflow,
    isUnhappy: overflow.length > 0
  };
}


