function renderStarRating(ovr){
  let fullStars = 1;
  let halfStar = false;
  if(ovr >= 85){ fullStars = 5; }
  else if(ovr >= 80){ fullStars = 4; halfStar = true; }
  else if(ovr >= 75){ fullStars = 4; }
  else if(ovr >= 70){ fullStars = 3; halfStar = true; }
  else if(ovr >= 65){ fullStars = 3; }
  else if(ovr >= 60){ fullStars = 2; }
  else if(ovr >= 55){ fullStars = 1; halfStar = true; }
  else { fullStars = 1; }

  let html = '';
  for(let i=0; i<fullStars; i++) html += '<span style="color:#f59e0b">★</span>';
  if(halfStar) html += '<span style="color:#f59e0b;opacity:0.8">★</span>';
  const empty = 5 - fullStars - (halfStar ? 1 : 0);
  for(let i=0; i<empty; i++) html += '<span style="color:#cbd5e1">★</span>';
  return html;
}



// Estado de partida em tempo real
let liveMatchState=null;
let liveMatchTimer=null;

// =========================================================================
// SISTEMA DE AUTENTICAÇÃO LOCAL, MULTI-SAVES & ÁREA DE ADMIN (GITHUB READY)
// =========================================================================
const AFM_AUTH_KEY = 'afm_accounts_v1';
const AFM_SESSION_KEY = 'afm_active_user_v1';

function recordAFMError(type, error){
  const message = error?.message || String(error || 'Falha interna sem mensagem legível');
  window.AFMErrorLog?.record(type, message, error instanceof Error ? { stack: error.stack } : {});
}

function getStoredAccounts(){
  let accs = [];
  try {
    const raw = localStorage.getItem(AFM_AUTH_KEY);
    if(raw) accs = JSON.parse(raw);
  } catch(e){ recordAFMError('local-account-read', e); }
  if(!Array.isArray(accs)) accs = [];
  return accs.filter(a => a && typeof a.username === 'string');


}

function saveStoredAccounts(accs){
  try {
    localStorage.setItem(AFM_AUTH_KEY, JSON.stringify(accs));
    return true;
  } catch(e){ recordAFMError('local-account-write', e); }
  return false;
}

function formatSaveTimestamp(value){
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : date.toLocaleString('pt-BR');
}

function getActiveAccount(){
  try {
    const user = window.AFM_DB?.getUser();
    if(!user) return null;
    const accounts = getStoredAccounts();
    const activeU = (user.username || user.id || '').toLowerCase();
    const account = accounts.find(a => (a.username || '').toLowerCase() === activeU);
    return account ? { ...account, role: window.AFM_DB?.isAdmin?.() === true ? 'admin' : 'player' } : null;
  } catch(e){
    recordAFMError('active-account-read', e);
    return null;
  }
}

function setActiveAccount(userId){
  if(userId) localStorage.setItem(AFM_SESSION_KEY, String(userId).toLowerCase().trim());
  else localStorage.removeItem(AFM_SESSION_KEY);
}

async function activateAuthenticatedUser(user){
  if(!user || (!user.username && !user.id)) return { success: false, error: 'A autenticação não retornou uma sessão válida.' };
  const userIdentifier = String(user.username || user.id).toLowerCase().trim();
  const accounts = getStoredAccounts();
  let account = accounts.find(a => (a.username || '').toLowerCase() === userIdentifier);
  let importedLegacyState = false;
  let importedLegacyUsername = null;
  if(!account){
    const previousUsername = localStorage.getItem(AFM_SESSION_KEY);
    const legacy = accounts.find(a => a.username.toLowerCase() === (previousUsername || '').toLowerCase());
    importedLegacyUsername = legacy?.username || null;
    account = legacy
      ? { ...legacy, username: userIdentifier, saves: legacy.saves || [] }
      : { username: userIdentifier, saves: [], createdAt: new Date().toISOString() };
    account.name = user.name || user.user_metadata?.display_name || account.name || userIdentifier;
    account.role = 'player';
    if(legacy) accounts.splice(accounts.indexOf(legacy), 1, account);
    else accounts.push(account);
    if(legacy && state?.club && (!state.userOwner || state.userOwner.toLowerCase() === legacy.username.toLowerCase())){
      state.userOwner = userIdentifier;
      importedLegacyState = true;
    }
  }
  account.role = (userIdentifier === 'aquino' || user.role === 'admin') ? 'admin' : (user.role || account.role || 'player');
  if(user.password) account.password = user.password;
  saveStoredAccounts(accounts);
  setActiveAccount(userIdentifier);
  if(importedLegacyUsername){
    for(const slot of [1, 2, 3]){
      try {
        const key = `afm_save_slot_${slot}`;
        const entry = JSON.parse(localStorage.getItem(key) || 'null');
        if(entry?.club && (!entry.owner || entry.owner.toLowerCase() === importedLegacyUsername.toLowerCase())){
          entry.owner = user.id;
          entry.id = `save_${user.id}_slot${slot}_${norm(entry.club)}`;
          localStorage.setItem(key, JSON.stringify(entry));
        }
      } catch(e){ recordAFMError('legacy-save-migration', e); }
    }
  }
  if(importedLegacyState) save();
  const synced = await window.AFM_DB.syncUser(userIdentifier);
  if(!synced.ok){
    recordAFMError('save-sync', synced.error);
    console.warn('[AFM] Sincronização de saves indisponível:', synced.error);
  }
  for(const entry of getUserSaveSlots(userIdentifier)){
    if(entry?.data?.club){
      const saved = await window.AFM_DB.saveSlot(userIdentifier, entry.slot, entry);
      if(!saved.ok) recordAFMError('save-sync', saved.error);
    }
  }
  return { success: true, user: account };
}

async function loginUser(username, password){
  const cleanUser = (username || '').trim();
  if(!cleanUser) return { success: false, error: 'Digite seu nome de usuário.' };
  if(!password) return { success: false, error: 'Digite sua senha de acesso.' };
  const result = await window.AFM_DB.signIn(cleanUser, password);
  if(!result.ok) return { success: false, error: result.error };
  return activateAuthenticatedUser(result.user);
}
window.loginUser = loginUser;
window.getStoredAccounts = getStoredAccounts;

async function registerUser(username, password, name){
  const cleanId = (username || '').trim();
  if(!cleanId || cleanId.length < 2) return { success: false, error: 'Informe um nome de usuário válido.' };
  if((password || '').length < 4) return { success: false, error: 'A senha deve ter pelo menos 4 caracteres.' };
  const result = await window.AFM_DB.signUp(cleanId, password, name || '');
  if(!result.ok) return { success: false, error: result.error };
  if(result.needsConfirmation) return { success: true, needsConfirmation: true };
  return activateAuthenticatedUser(result.user);
}

async function logoutUser(){
  const result = await window.AFM_DB.signOut();
  if(!result.ok) return toast(result.error);
  setActiveAccount(null);
  state = null;
  toast('Você saiu da sua conta.');
  render();
}

function getUserSaveSlots(username){
  const cleanU = (username || getActiveAccount()?.username || 'aquino').trim().toLowerCase();
  const accs = getStoredAccounts();
  const acc = accs.find(a => (a.username || '').toLowerCase() === cleanU);
  const saves = acc?.saves || [];

  return [1, 2, 3].map(slotNum => {
    let s = saves.find(x => x.slot === slotNum);

    try {
      const uRaw = localStorage.getItem(`afm_save_${cleanU}_slot_${slotNum}`);
      if(uRaw){
        const parsed = JSON.parse(uRaw);
        if(parsed && parsed.club) s = parsed;
      }
    } catch(e){ recordAFMError('save-slot-read', e); }

    // 1. Carregar/complementar a partir do slot dedicado do localStorage
    try {
      const raw = localStorage.getItem(`afm_save_slot_${slotNum}`);
      if(raw){
        const parsed = JSON.parse(raw);
        if(parsed && parsed.club && (!parsed.owner || parsed.owner.toLowerCase() === cleanU)){
          s = s ? { ...s, ...parsed } : parsed;
        }
      }
    } catch(e){ recordAFMError('save-slot-read', e); }

    // 2. Fallback Crítico para o Slot 1: procurar no save primário STORAGE ('aquino_futebol_manager_2026_v1')
    if(slotNum === 1 && (!s || (!s.data && !s.club))){
      try {
        const legacyRaw = localStorage.getItem(STORAGE);
        if(legacyRaw){
          const leg = JSON.parse(legacyRaw);
          if(leg && leg.club){
            s = {
              slot: 1,
              id: `save_${cleanU}_slot1_${norm(leg.club)}`,
              owner: cleanU,
              club: leg.club,
              manager: leg.manager || 'Treinador',
              season: leg.season || 2026,
              date: leg.date || '2026-01-01',
              round: Number(leg.round) || 0,
              balance: Number(leg.balance) || 0,
              updatedAt: new Date().toLocaleString('pt-BR'),
              data: leg
            };
            try { localStorage.setItem('afm_save_slot_1', JSON.stringify(s)); } catch(e){ recordAFMError('save-slot-migration', e); }
          }
        }
      } catch(e){ recordAFMError('legacy-save-read', e); }
    }

    // 3. Normalização: se for save plano antigo (sem chave .data), embrulhar adequadamente
    if(s && !s.data && s.club){
      s = {
        slot: slotNum,
        id: s.id || `save_${cleanU}_slot${slotNum}_${norm(s.club)}`,
        owner: s.owner || cleanU,
        club: s.club,
        manager: s.manager || 'Treinador',
        season: s.season || 2026,
        date: s.date || '2026-01-01',
        round: Number(s.round) || 0,
        balance: Number(s.balance) || 0,
        updatedAt: s.updatedAt || s.date || new Date().toLocaleString('pt-BR'),
        data: clone(s)
      };
      try { localStorage.setItem(`afm_save_slot_${slotNum}`, JSON.stringify(s)); } catch(e){ recordAFMError('save-slot-migration', e); }
    }

    return s || null;
  });
}

function save(){
  if(!state) return false;
  processContinentalFixturesBefore(state.date);
  if(Array.isArray(state.news) && state.news.length > 50){
    state.news = state.news.slice(0, 50);
  }
  if(Array.isArray(state.marketWorldFeed) && state.marketWorldFeed.length > 30){
    state.marketWorldFeed = state.marketWorldFeed.slice(0, 30);
  }
  if(Array.isArray(state.seasonHistory) && state.seasonHistory.length > 20){
    state.seasonHistory = state.seasonHistory.slice(0, 20);
  }

  const slotNum = Math.max(1, Math.min(3, Number(state.userSlot) || 1));
  state.userSlot = slotNum;

  // Prepara payload compacto omitindo worldGenerated (recriado dinamicamente no load para economizar 95% de quota)
  const savePayload = clone(state);
  delete savePayload.worldGenerated;

  let localSaved = false;
  // 1. Salvar no STORAGE primário apenas se for Slot 1 (evita corrupção de outros slots)
  if(slotNum === 1){
    try {
      localStorage.setItem(STORAGE, JSON.stringify(savePayload));
      localSaved = true;
    } catch(e){ recordAFMError('local-save-write', e); }
  }

  const user = getActiveAccount() || { username: state.userOwner || 'local', name: state.manager || 'Treinador' };
  state.userOwner = user.username;
  const saveId = `save_${state.userOwner}_slot${slotNum}_${norm(state.club)}`;
  state.saveId = saveId;

  const saveHeader = {
    slot: slotNum,
    id: saveId,
    owner: state.userOwner,
    club: state.club,
    manager: state.manager || user.name || 'Treinador',
    season: state.season,
    date: state.date,
    round: state.round,
    balance: state.balance,
    updatedAt: new Date().toISOString()
  };

  const saveEntry = {
    ...saveHeader,
    data: savePayload
  };

  // 2. Salvar no slot dedicado no localStorage (garante persistência isolada e completa de cada slot)
  try {
    localStorage.setItem(`afm_save_slot_${slotNum}`, JSON.stringify(saveEntry));
    if(state.userOwner) localStorage.setItem(`afm_save_${state.userOwner.toLowerCase()}_slot_${slotNum}`, JSON.stringify(saveEntry));
    localSaved = true;
  } catch(e){ recordAFMError('local-save-write', e); }

  if(!localSaved){
    if(!window.__afmStorageWarning){
      toast('Falha ao salvar localmente. Libere espaço no navegador e tente novamente.', 6000);
      window.__afmStorageWarning = true;
    }
    return false;
  }
  window.__afmStorageWarning = false;

  // 3. Salvar na lista de contas do sistema (armazena cabeçalho leve para economizar 95% de quota)
  const accs = getStoredAccounts();
  let acc = accs.find(a => a.username === state.userOwner);
  if(acc){
    acc.saves = acc.saves || [];
    const existingIdx = acc.saves.findIndex(s => s.slot === slotNum);
    const lightweightHeader = { ...saveHeader };
    if(existingIdx >= 0){
      acc.saves[existingIdx] = lightweightHeader;
    } else {
      acc.saves.push(lightweightHeader);
    }
    acc.saves = acc.saves.filter(s => s.slot >= 1 && s.slot <= 3).sort((a,b) => a.slot - b.slot);
    saveStoredAccounts(accs);

    // 4. Sincronizar save com o Supabase Cloud
    if(window.AFM_DB && typeof window.AFM_DB.saveSlot === 'function'){
      window.AFM_DB.saveSlot(state.userOwner, slotNum, saveEntry)
        .then(result => { if(!result?.ok) window.AFMErrorLog?.record('save-sync', result?.error || 'Falha ao sincronizar save'); })
        .catch(error => window.AFMErrorLog?.record('save-sync', error?.message || 'Falha ao sincronizar save'));
    }
  }

  return true;
}

function load(){
  try {
    return JSON.parse(localStorage.getItem(STORAGE) || 'null');
  } catch(e){
    recordAFMError('local-save-read', e);
    return null;
  }
}

function loadUserSlot(slotNum, ownerUsername = null){
  slotNum = Math.max(1, Math.min(3, Number(slotNum) || 1));
  const username = (ownerUsername || state?.userOwner || getActiveAccount()?.username || 'aquino').toLowerCase();
  const accs = getStoredAccounts();
  const acc = accs.find(a => (a.username || '').toLowerCase() === username);
  
  let saveEntry = null;

  // 1. Carrega do slot dedicado isolado do usuário
  try {
    const uRaw = localStorage.getItem(`afm_save_${username}_slot_${slotNum}`);
    if(uRaw) saveEntry = JSON.parse(uRaw);
  } catch(e){ recordAFMError('save-slot-read', e); }

  // 1b. Fallback para slot compartilhado se pertencer ao usuário
  try {
    const raw = localStorage.getItem(`afm_save_slot_${slotNum}`);
    if(raw) saveEntry = JSON.parse(raw);
  } catch(e){ recordAFMError('save-slot-read', e); }

  const hasCompleteData = (e) => e && ((e.data && e.data.squad) || (e.squad && e.club));

  // 2. Se o slot dedicado não possuir payload completo e for slot 1, consulta STORAGE
  if(!hasCompleteData(saveEntry) && slotNum === 1){
    try {
      const legRaw = localStorage.getItem(STORAGE);
      if(legRaw){
        const leg = JSON.parse(legRaw);
        if(leg && leg.club && Array.isArray(leg.squad)) {
          saveEntry = { data: leg, club: leg.club, userSlot: 1 };
        }
      }
    } catch(e){ recordAFMError('legacy-save-read', e); }
  }

  // 3. Se ainda não encontrado, busca na conta
  if(!hasCompleteData(saveEntry)){
    const accSave = (acc?.saves || []).find(s => s.slot === slotNum);
    if(accSave && hasCompleteData(accSave)){
      saveEntry = accSave;
    } else if(accSave && !saveEntry){
      saveEntry = accSave;
    }
  }

  if(!saveEntry || (!saveEntry.data && !saveEntry.club)){
    toast(`O Slot ${slotNum} está vazio.`);
    return false;
  }

  const rawData = saveEntry.data || saveEntry;
  state = clone(rawData);
  state.userSlot = slotNum;
  state.userOwner = username;
  state = migrate(state);
  save();
  view = 'central';
  toast(`Campanha do ${clubDisplayName(state.club)} (Slot ${slotNum}) carregada com sucesso!`);
  render();
  return true;
}

function deleteUserSlot(slotNum, ownerUsername = null){
  slotNum = Math.max(1, Math.min(3, Number(slotNum) || 1));
  const username = (ownerUsername || getActiveAccount()?.username || 'aquino').toLowerCase();
  if(!confirm(`Deseja realmente excluir a campanha do Slot ${slotNum}? Esta ação não pode ser desfeita.`)) return;
  
  try {
    localStorage.removeItem(`afm_save_slot_${slotNum}`);
    localStorage.removeItem(`afm_save_${username}_slot_${slotNum}`);
    if(slotNum === 1) localStorage.removeItem(STORAGE);
  } catch(e){
    recordAFMError('save-delete-local', e);
    toast('Não foi possível excluir o save local. Verifique o armazenamento do navegador.');
    return false;
  }

  const accs = getStoredAccounts();
  const acc = accs.find(a => a.username.toLowerCase() === username) || accs.find(a => a.username.toLowerCase() === 'aquino');
  if(acc){
    acc.saves = (acc.saves || []).filter(s => s.slot !== slotNum);
    if(!saveStoredAccounts(accs)){
      toast('O save local foi apagado, mas a lista de campanhas não pôde ser atualizada.');
      return false;
    }
  }

  // Deletar da nuvem (Supabase)
  if(window.AFM_DB && typeof window.AFM_DB.deleteSlot === 'function'){
    window.AFM_DB.deleteSlot(username, slotNum)
      .then(result => { if(!result?.ok) recordAFMError('save-delete', result.error); })
      .catch(error => recordAFMError('save-delete', error));
  }

  toast(`Campanha do Slot ${slotNum} excluída com sucesso.`);
  if(state && Number(state.userSlot) === slotNum){
    state = null;
    render();
  } else if(state){
    render();
  } else {
    renderSetup($('#app'));
  }
}

function loadUserSave(saveId, ownerUsername = null){
  const username = ownerUsername || getActiveAccount()?.username;
  if(!username){ toast('Nenhum usuário ativo para carregar o save.'); return; }
  const accs = getStoredAccounts();
  const acc = accs.find(a => a.username.toLowerCase() === username.toLowerCase());
  if(!acc) return;
  const saveEntry = (acc.saves || []).find(s => s.id === saveId);
  if(saveEntry && saveEntry.slot) return loadUserSlot(saveEntry.slot, username);
  if(!saveEntry || !saveEntry.data){ toast('Save não encontrado.'); return; }
  state = clone(saveEntry.data);
  state = migrate(state);
  localStorage.setItem(STORAGE, JSON.stringify(state));
  view = 'central';
  toast(`Save do ${clubDisplayName(state.club)} carregado com sucesso!`);
  render();
}

function deleteUserSave(saveId, ownerUsername = null){
  const username = ownerUsername || getActiveAccount()?.username;
  if(!username) return;
  if(!confirm('Deseja realmente excluir este save? Esta ação não pode ser desfeita.')) return;
  const accs = getStoredAccounts();
  const acc = accs.find(a => a.username.toLowerCase() === username.toLowerCase());
  if(!acc) return;
  const sEntry = (acc.saves || []).find(s => s.id === saveId);
  if(sEntry && sEntry.slot){
    try {
      localStorage.removeItem(`afm_save_${username.toLowerCase()}_slot_${sEntry.slot}`);
      localStorage.removeItem(`afm_save_slot_${sEntry.slot}`);
    } catch(e){}
    if(window.AFM_DB?.deleteSlot) window.AFM_DB.deleteSlot(username, sEntry.slot).catch(()=>{});
  }
  acc.saves = (acc.saves || []).filter(s => s.id !== saveId);
  saveStoredAccounts(accs);
  toast('Save excluído com sucesso.');
  render();
}

