function clubStateCompId(clubName){
  const nameNorm = norm(clubName);
  if(CLUB_TO_STATE_COMP[nameNorm]) return CLUB_TO_STATE_COMP[nameNorm];

  // Saved rosters are equally authoritative: hydration can lag behind a promoted save.
  const tMap = Object.assign({}, window.COMPETITION_TEAMS || {}, state?.competitionTeams || {});
  for(const [cId, list] of Object.entries(tMap)){
    if(cId.startsWith('bra-est-') && Array.isArray(list)){
      if(list.some(c => norm(typeof c === 'string' ? c : c?.name) === nameNorm)) return cId;
    }
  }
  const clubObj = clubByName(clubName);
  const comp = clubObj?.competition || '';
  if(comp.includes('Candango')) return 'bra-est-df';
  if(comp.includes('Paulista')) return 'bra-est-sp';
  if(comp.includes('Carioca')) return 'bra-est-rj';
  if(comp.includes('Mineiro')) return 'bra-est-mg';
  if(comp.includes('Gaúcho') || comp.includes('Gaucho')) return 'bra-est-rs';
  if(comp.includes('Paranaense')) return 'bra-est-pr';
  if(comp.includes('Catarinense')) return 'bra-est-sc';
  if(comp.includes('Baiano')) return 'bra-est-ba';
  if(comp.includes('Cearense')) return 'bra-est-ce';
  if(comp.includes('Goiano')) return 'bra-est-go';
  if(comp.includes('Pernambucano')) return 'bra-est-pe';
  // A legacy save can have a national Série A-D membership but no estadual entry.
  if(['bra-a','bra-b','bra-c','bra-d'].some(id => (tMap[id] || []).some(c => norm(typeof c === 'string' ? c : c?.name) === nameNorm))){
    const clubText = norm(`${clubName} ${clubObj?.name || ''} ${clubObj?.state || ''} ${clubObj?.uf || ''} ${clubObj?.competition || ''}`);
    if(/\b(brasilia|aruc|gama|ceilandia|sobradinho|samambaia|paranoa|capital-df|real brasilia|brasiliense)\b/.test(clubText)) return 'bra-est-df';
    if(/\b(sao paulo|paulista|bragantino|corinthians|palmeiras|santos|sao bernardo|mirassol)\b/.test(clubText)) return 'bra-est-sp';
    if(/\b(rio de janeiro|carioca|flamengo|fluminense|vasco|botafogo|volta redonda)\b/.test(clubText)) return 'bra-est-rj';
    if(/\b(mineiro|belo horizonte|cruzeiro|atletico-mg|america-mg)\b/.test(clubText)) return 'bra-est-mg';
    if(/\b(gaucho|rio grande do sul|porto alegre|gremio|internacional|juventude|caxias)\b/.test(clubText)) return 'bra-est-rs';
    if(/\b(paranaense|curitiba|athletico-pr|operario-pr|coritiba|maringa)\b/.test(clubText)) return 'bra-est-pr';
    if(/\b(catarinense|santa catarina|chapecoense|figueirense|avai|criciuma|brusque)\b/.test(clubText)) return 'bra-est-sc';
    if(/\b(baiano|salvador|bahia|vitoria)\b/.test(clubText)) return 'bra-est-ba';
    if(/\b(cearense|fortaleza|ceara|ferroviario)\b/.test(clubText)) return 'bra-est-ce';
    if(/\b(goiano|goiania|goias|vila nova|atletico-go)\b/.test(clubText)) return 'bra-est-go';
    if(/\b(pernambucano|recife|sport|nautico|santa cruz)\b/.test(clubText)) return 'bra-est-pe';
  }
  return 'bra-est-sp';
}

// Returns all roster memberships; a Brazilian club may play both national and estadual leagues.
function getClubCompetitionIds(clubName){
  if(!clubName) return [];
  const key = norm(clubName), ids = new Set();
  for(const map of [state?.competitionTeams || BASE_COMPETITION_TEAMS || window.COMPETITION_TEAMS].filter(Boolean)){
    for(const [id, roster] of Object.entries(map)){
      if(Array.isArray(roster) && roster.some(name => norm(typeof name === 'string' ? name : name?.name) === key)) ids.add(id);
    }
  }
  // A national division and an estadual are simultaneous memberships.
  const nationalId = getClubPrimaryCompetitionId(clubName, state?.compId);
  if(['bra-a','bra-b','bra-c','bra-d'].includes(nationalId)) ids.add(nationalId);
  const stateId = clubStateCompId(clubName);
  const stateRoster = state?.competitionTeams?.[stateId] || BASE_COMPETITION_TEAMS?.[stateId] || window.COMPETITION_TEAMS?.[stateId] || [];
  // Membership can be derived from the state association even when an old save lost the roster entry.
  if(stateId && (stateRoster.some(name=>norm(typeof name==='string'?name:name?.name)===key) || ['bra-a','bra-b','bra-c','bra-d'].includes(nationalId))) ids.add(stateId);
  return [...ids];
}
function getClubPrimaryCompetitionId(clubName, preferredCompId = null){
  if(!clubName) return preferredCompId || 'bra-a';
  const nameNorm = norm(clubName);
  const tMap = state?.competitionTeams || BASE_COMPETITION_TEAMS || window.COMPETITION_TEAMS || {};

  // A promoted club's explicit saved division has priority over stale historical
  // club metadata, even while the global roster is being hydrated.
  if(['bra-a','bra-b','bra-c','bra-d'].includes(preferredCompId) && compById(preferredCompId)){
    const savedTeams = Array.isArray(state?.teams) ? state.teams : [];
    const persistedRoster = state?.competitionTeams?.[preferredCompId] || tMap[preferredCompId] || [];
    if(savedTeams.some(team => norm(team?.name) === nameNorm) || persistedRoster.some(team => norm(typeof team === 'string' ? team : team?.name) === nameNorm)) return preferredCompId;
  }

  // Em saves de temporadas anteriores, a divisão nacional salva é dinâmica e deve prevalecer
  // sobre o catálogo histórico fixo do clube, desde que o clube conste na divisão salva.
  if(['bra-a','bra-b','bra-c','bra-d'].includes(preferredCompId) && compById(preferredCompId) && Array.isArray(tMap[preferredCompId])){
    const savedTeams = Array.isArray(state?.teams) ? state.teams : [];
    if(savedTeams.some(team => norm(team.name) === nameNorm) || tMap[preferredCompId].some(team => norm(team) === nameNorm)) return preferredCompId;
  }
  if(preferredCompId){
    const prefComp = compById(preferredCompId);
    if(prefComp && eligibleClubNames(prefComp).some(c => norm(c) === nameNorm)) return preferredCompId;
  }
  // Clubes candangos sem divisão nacional (Brasília, ARUC, etc.)
  if(nameNorm === 'brasilia' || nameNorm.includes('brasilia fc') || nameNorm === 'aruc' || nameNorm === 'paranoa' || nameNorm === 'samambaia' || nameNorm === 'sobradinho'){
    return 'bra-est-df';
  }

  // A atribuição dinâmica da temporada prevalece sobre o campeonato histórico
  // gravado no objeto estático do clube (que não acompanha acessos/rebaixamentos).
  const brDivs = ['bra-a', 'bra-b', 'bra-c', 'bra-d'];
  for(const divId of brDivs){
    if(Array.isArray(tMap[divId]) && tMap[divId].some(c => norm(c) === nameNorm)){
      return divId;
    }
  }

  const clubObj = clubByName(clubName);
  if(clubObj?.competition){
    const matchedComp = (window.COMPETITIONS||[]).find(c => norm(c.name) === norm(clubObj.competition));
    if(matchedComp && (matchedComp.id in tMap || !matchedComp.id.startsWith('bra-est-'))){
      return matchedComp.id;
    }
  }

  // 2. Principais ligas internacionais
  const intlLigas = ['eng-1', 'eng-2', 'esp-1', 'esp-2', 'ita-1', 'ger-1', 'fra-1', 'por-1', 'ned-1', 'arg-1', 'uru-1', 'chi-1', 'col-1', 'par-1', 'ecu-1', 'per-1', 'bol-1', 'ven-1', 'ksa-1', 'jpn-1', 'kor-1', 'chn-1', 'qat-1', 'uae-1'];
  for(const lId of intlLigas){
    if(Array.isArray(tMap[lId]) && tMap[lId].some(c => norm(c) === nameNorm)){
      return lId;
    }
  }

  // 3. Estaduais
  const estId = clubStateCompId(clubName);
  if(estId && tMap[estId] && tMap[estId].some(c => norm(c) === nameNorm)){
    return estId;
  }

  // 4. Qualquer outra competição em tMap
  for(const [cId, list] of Object.entries(tMap)){
    if(Array.isArray(list) && list.some(c => norm(c) === nameNorm)){
      return cId;
    }
  }

  if(clubObj?.country === 'Brasil') return 'bra-a';
  return 'eng-1';
}

function compBaseStrength(comp){
  if(!comp)return 65;
  if(comp.id==='bra-a')return 78;if(comp.id==='bra-b')return 71;if(comp.id==='bra-c')return 64;if(comp.id==='bra-d')return 59;
  if(comp.continent==='Europa')return /champions|premier|laliga|serie a|bundesliga|ligue 1/i.test(comp.name)?80:73;
  if(comp.continent==='Ásia')return 69;
  if(comp.country==='Brasil'&&comp.id.startsWith('bra-est'))return 61;
  return 68;
}

function inferClubMeta(p){
  const league=String(p?.league||'');
  const rules=[
   [/premier league/i,'Inglaterra','Premier League'],[/championship/i,'Inglaterra','EFL Championship'],[/laliga|la liga/i,'Espanha','LaLiga'],[/serie a/i,'Itália','Serie A'],
   [/bundesliga/i,'Alemanha','Bundesliga'],[/ligue 1/i,'França','Ligue 1'],[/primeira liga|liga portugal/i,'Portugal','Primeira Liga'],[/eredivisie/i,'Países Baixos','Eredivisie'],
   [/argentina|liga profesional/i,'Argentina','Liga Profesional Argentina'],[/saudi|roshn/i,'Arábia Saudita','Saudi Pro League'],[/j1 league|japan/i,'Japão','J1 League'],[/k league/i,'Coreia do Sul','K League 1'],[/chinese super league|china/i,'China','Chinese Super League']
  ];
  for(const [rx,country,competition] of rules) if(rx.test(league))return {country,competition};
  return {country:p?.clubCountry||p?.teamCountry||'Outro',competition:league||'Outros clubes'};
}

function buildClubs(){
  const map=new Map();
  (window.BASE_CLUBS||[]).forEach(c=>map.set(norm(c.name),clone(c)));
  const liveByClub={};
  for(const p of livePlayers){if(!p.club)continue;(liveByClub[p.club]??=[]).push(p)}
  for(const [name,ps] of Object.entries(liveByClub)){
    const vals=ps.map(playerOverall).filter(Boolean);const avg=Math.round(vals.reduce((a,b)=>a+b,0)/(vals.length||1));const key=norm(name);const existing=map.get(key);const meta=inferClubMeta(ps[0]);
    if(existing){existing.atk=Math.round(((existing.atk||avg)+avg)/2);existing.mid=Math.round(((existing.mid||avg)+avg)/2);existing.def=Math.round(((existing.def||avg)+avg)/2);existing.playerCount=ps.length;}
    else map.set(key,{name,country:meta.country,competition:meta.competition,stadium:'Estádio do clube',atk:avg,mid:avg,def:avg,budget:Math.max(.4,(avg-52)*2.2),playerCount:ps.length});
  }
  for(const [compId,names] of Object.entries(teamMap)){
    const comp=compById(compId);if(!comp)continue;const base=compBaseStrength(comp);
    names.forEach((name,i)=>{const key=norm(name);if(!map.has(key)){const wiggle=(hashStr(name)%7)-3;const s=clamp(base+wiggle,48,88);map.set(key,{name,country:comp.country==='CONMEBOL'||comp.country==='UEFA'||comp.country==='AFC'?'Outro':comp.country,competition:comp.name,stadium:'Estádio do clube',atk:s+rnd(-1,1),mid:s+rnd(-1,1),def:s+rnd(-1,1),budget:Math.max(.25,Math.pow(Math.max(3,s-48),1.35)/2.6)});}});
  }
  return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
}

function regionCountries(continent){
  if(continent==='América do Sul')return ['Brasil','Argentina','Uruguai','Chile','Colômbia','Equador','Paraguai','Peru','Bolívia','Venezuela'];
  if(continent==='Europa')return ['Inglaterra','Espanha','Itália','Alemanha','França','Portugal','Países Baixos','Bélgica','Turquia','Escócia','Áustria','Suíça','Grécia','Croácia','Sérvia','Tchéquia','Dinamarca','Noruega','Suécia'];
  return ['Arábia Saudita','Japão','Coreia do Sul','China','Catar','Emirados Árabes Unidos','Irã','Índia','Tailândia','Austrália'];
}

function eligibleClubNames(comp, rosterOverride = null){
  if(!comp)return [];
  // The active career owns its seasonal roster. Static teamMap is the immutable
  // starting catalog and must never be changed by promotions/relegations.
  const savedRoster = rosterOverride?.[comp.id] || state?.competitionTeams?.[comp.id];
  if(Array.isArray(savedRoster)&&savedRoster.length)return [...savedRoster];
  const baseRoster = (typeof BASE_COMPETITION_TEAMS !== 'undefined' ? BASE_COMPETITION_TEAMS?.[comp.id] : null) || teamMap[comp.id];
  if(Array.isArray(baseRoster)&&baseRoster.length)return [...baseRoster];
  const exact=clubs.filter(c=>norm(c.competition)===norm(comp.name)).map(c=>c.name);
  if(exact.length)return [...new Set(exact)];
  if(['CONMEBOL','UEFA','AFC'].includes(comp.country))return clubs.filter(c=>regionCountries(comp.continent).includes(c.country)).map(c=>c.name);
  if(/cup|copa|taça|pokal|king/i.test(comp.name))return clubs.filter(c=>c.country===comp.country).map(c=>c.name);
  if(comp.id && comp.id.startsWith('bra-est-')) return []; // Jamais vazar todos os clubes do Brasil para estaduais vazios
  return clubs.filter(c=>c.country===comp.country).map(c=>c.name);
}

function competitionClubs(comp,selected,rosterOverride=null){
  let names=eligibleClubNames(comp,rosterOverride);
  if(selected&&!names.some(x=>norm(x)===norm(selected)))names.unshift(selected);
  const target=comp.teams||Math.max(10,names.length);
  const base=compBaseStrength(comp);
  const out=names.map(name=>clubByName(name)||{name,country:comp.country,competition:comp.name,stadium:'Estádio do clube',atk:base,mid:base,def:base,budget:5});
  const selectedRoster = rosterOverride?.[comp.id] || state?.competitionTeams?.[comp.id];
  const hasSavedRoster = Array.isArray(selectedRoster) && selectedRoster.length > 0;
  const baseRoster = (typeof BASE_COMPETITION_TEAMS !== 'undefined' ? BASE_COMPETITION_TEAMS?.[comp.id] : null) || teamMap[comp.id];
  const hasBaseRoster = Array.isArray(baseRoster) && baseRoster.length > 0;
  if(!hasBaseRoster && !hasSavedRoster){
    while(out.length<target){const n=out.length+1,s=clamp(base+rnd(-5,5),48,88);out.push({name:`Clube ${n} — ${comp.country}`,country:comp.country,competition:comp.name,stadium:'Estádio Municipal',atk:s,mid:s,def:s,budget:Math.max(.3,(s-50)*1.5)});}
  }
  if(selected && !hasBaseRoster && !hasSavedRoster){
    const sIdx = out.findIndex(x => norm(x.name) === norm(selected));
    if(sIdx >= target){
      const selItem = out.splice(sIdx, 1)[0];
      out.unshift(selItem);
    }
  }
  return hasBaseRoster || hasSavedRoster ? out : out.slice(0,target);
}

function generatedRosterForClub(club){
  const c=clubByName(club)||{name:club,country:'Outro',atk:66,mid:66,def:66};const base=strength(c);const arr=[];
  for(let i=0;i<25;i++){
    const pos=POSITIONS[i%POSITIONS.length];const o=clamp(base+((hashStr(club+'|'+i)%13)-6),45,91);const age=18+(hashStr('age|'+club+'|'+i)%18);const pot=clamp(o+(hashStr('pot|'+club+'|'+i)%10),o,94);const name=`${NAMES[(hashStr(club+'n'+i)%NAMES.length)]} ${LAST[(hashStr(club+'l'+i)%LAST.length)]}`;
    const p={id:`gen-${norm(club)}-${i}`,marketKey:`gen:${norm(club)}:${i}`,name,club,country:c.country||'Outro',pos,age,fc:o,pes:clamp(o+((i%3)-1),45,92),potential:pot,value:0,morale:70,fitness:100,owned:false};p.value=calcValueMi(p);arr.push(p);
  }
  return arr;
}

function buildWorldGenerated(){
  const counts=new Map();for(const p of livePlayers){const k=norm(p.club);if(k)counts.set(k,(counts.get(k)||0)+1)}
  const out=[];for(const c of clubs){const liveCount=counts.get(norm(c.name))||0;if(liveCount>=11)continue;const need=Math.max(4,22-liveCount);out.push(...generatedRosterForClub(c.name).slice(0,need));}return out;
}

function playersForClub(club,worldGenerated){
  const live=livePlayers.filter(p=>norm(p.club)===norm(club)).map((p,i)=>({...p,id:p.id||`live-${hashStr(playerKey(p))}`,marketKey:playerKey(p),morale:p.morale??70,fitness:p.fitness??100,owned:true,value:calcValueMi(p)}));
  if(live.length >= 11){
    return live.map(p=>({...p,club,owned:true,marketKey:playerKey(p)}));
  }
  const gen=(worldGenerated||[]).filter(p=>norm(p.club)===norm(club));
  return [...live,...gen].slice(0,25).map(p=>({...p,club,owned:true,marketKey:playerKey(p)}));
}

function stablePlayer(p){
  const wage = playerSalary(p);
  const contractUntil = playerContractUntil(p);
  return {...p, marketKey:playerKey(p), value:calcValueMi(p), wage, contractUntil};
}
function totalMonthlyPayroll(){
  return (state?.squad || []).reduce((acc, p) => acc + playerSalary(p), 0);
}
function payrollPerRound(){
  return Math.round(totalMonthlyPayroll() / 4);
}

function roundRobin(teamNames){let a=[...teamNames];if(a.length%2)a.push('FOLGA');const n=a.length,rounds=[];for(let r=0;r<n-1;r++){const games=[];for(let i=0;i<n/2;i++){const x=a[i],y=a[n-1-i];if(x!=='FOLGA'&&y!=='FOLGA')games.push(r%2?[y,x]:[x,y])}rounds.push(games);a=[a[0],a[n-1],...a.slice(1,n-1)]}return rounds.concat(rounds.map(rd=>rd.map(([h,a])=>[a,h])))}
function roundRobinSingleLeg(teamNames){const a0=[...teamNames];if(a0.length%2)a0.push('FOLGA');const n=a0.length,rounds=[],a=[...a0];for(let r=0;r<n-1;r++){const games=[];for(let i=0;i<n/2;i++){const x=a[i],y=a[n-1-i];if(x!=='FOLGA'&&y!=='FOLGA')games.push(r%2?[y,x]:[x,y])}rounds.push(games);a.splice(1,0,a.pop())}return rounds}
function leaguePhaseSchedule(teamNames,rounds=8){const out=[],seen=new Set();for(let r=0;r<rounds;r++){const used=new Set(),games=[],order=[...teamNames].sort(()=>Math.random()-.5);for(const t of order){if(used.has(t))continue;let opp=order.find(x=>x!==t&&!used.has(x)&&!seen.has([t,x].sort().join('|')));if(!opp)opp=order.find(x=>x!==t&&!used.has(x));if(!opp)continue;used.add(t);used.add(opp);seen.add([t,opp].sort().join('|'));games.push(r%2?[opp,t]:[t,opp])}out.push(games)}return out}
function groupSchedule(teamNames,size=4,homeAway=true){const groups=[];for(let i=0;i<teamNames.length;i+=size)groups.push(teamNames.slice(i,i+size));const groupRounds=groups.map(g=>homeAway?roundRobin(g):roundRobinSingleLeg(g));const max=Math.max(0,...groupRounds.map(x=>x.length)),out=[];for(let r=0;r<max;r++)out.push(groupRounds.flatMap(g=>g[r]||[]));return out}
function firstKnockoutRound(teamNames){const a=[...teamNames].sort(()=>Math.random()-.5),games=[];for(let i=0;i<a.length;i+=2)if(a[i+1])games.push([a[i],a[i+1]]);return [games]}
function buildSchedule(comp,teamNames){if(comp.type==='knockout')return firstKnockoutRound(teamNames);if(comp.type==='league-phase'||comp.type==='continental-league')return leaguePhaseSchedule(teamNames,comp.rounds||8);if(comp.id==='bra-d')return groupSchedule(teamNames,24,false);if(comp.type.includes('groups')||comp.type==='continental-groups')return groupSchedule(teamNames,comp.groupSize||4).slice(0,comp.rounds||999);const rr=roundRobin(teamNames);return comp.rounds?rr.slice(0,Math.min(comp.rounds,rr.length)):rr}

function defaultInfrastructure(club){
  const s=strength(club);const cap=clamp(Math.round((8000+(s-55)*1400)/1000)*1000,8000,65000);
  // shortcut: capacity remains estimated until verified seat counts are added to each club profile.
  const stadiumLevel = cap <= 14000 ? 1 : cap <= 30640 ? 2 : cap <= 49000 ? 3 : cap <= 72160 ? 4 : cap <= 90000 ? 5 : 6;
  return {
    stadium:{level:stadiumLevel,capacity:cap},
    parking:{level:0,spots:0},
    training:{level:1},academy:{level:1},medical:{level:1},admin:{level:1},store:{level:1},museum:{level:1},press:{level:1},marketing:{level:1},bank:{level:1}
  };
}

// -------------------------------------------------------------
// CATEGORIA DE BASE (JUNIORES - 15 A 18 ANOS)
// -------------------------------------------------------------
function generateYouthPlayer(academyLevel=1, fixedAge=null, fixedPos=null){
  const lvl = clamp(Number(academyLevel) || 1, 1, 8);
  // Idade estritamente entre 15 e 18 anos conforme especificado
  const age = fixedAge ? clamp(Math.round(fixedAge), 15, 18) : rnd(15, 18);
  const pos = fixedPos || POSITIONS[rnd(0, POSITIONS.length - 1)];
  const firstName = NAMES[rnd(0, NAMES.length - 1)];
  const lastName = LAST[rnd(0, LAST.length - 1)];
  const name = `${firstName} ${lastName}`;

  // Quanto maior o nível da Categoria de Base, maior o Overall e Potencial gerado
  const baseOvr = Math.round(clamp(53 + (lvl * 3.0) + (Math.random() * 6 - 2), 52, 84));
  const basePot = Math.round(clamp(baseOvr + 10 + (lvl * 1.5) + (Math.random() * 6), baseOvr + 5, 96));

  const id = `youth-${Date.now()}-${rnd(100, 9999)}`;
  const p = {
    id,
    marketKey: `youth:${id}`,
    name,
    club: state?.club || 'Clube',
    country: 'Brasil',
    pos,
    age,
    fc: baseOvr,
    pes: baseOvr,
    potential: basePot,
    morale: 80,
    fitness: 100,
    isYouth: true,
    value: 0
  };
  p.value = calcValueMi(p);
  return p;
}

function generateInitialYouthAcademy(academyLevel=1, clubName=null){
  const club = clubName || state?.club || 'Clube';
  const positions = ['GK', 'CB', 'LB', 'RB', 'DM', 'CM', 'RW', 'LW', 'ST'];
  const players = [];
  const count = 7;
  for(let i = 0; i < count; i++){
    const pos = positions[i % positions.length];
    const age = 15 + (i % 4); // 15, 16, 17, 18 anos estritamente
    const p = generateYouthPlayer(academyLevel, age, pos);
    p.club = club;
    players.push(p);
  }
  return players;
}

function boostYouthAcademyOnUpgrade(newLevel){
  if(!Array.isArray(state.youthAcademy)) state.youthAcademy = [];
  state.youthAcademy.forEach(p => {
    p.potential = clamp((p.potential || playerOverall(p)) + 2, playerOverall(p) + 4, 96);
  });
  const topProspect = generateYouthPlayer(newLevel, rnd(15, 16));
  topProspect.potential = Math.min(96, topProspect.potential + 4);
  state.youthAcademy.unshift(topProspect);
  state.news.unshift(`🌱 A Categoria de Base foi ampliada para o Nível ${newLevel}! O jovem prodígio ${topProspect.name} (${topProspect.pos}, ${topProspect.age} anos, POT ${topProspect.potential}) ingressou na base.`);
}

function processYouthDevelopment(){
  if(!Array.isArray(state.youthAcademy)) return;
  const acadLvl = state.infrastructure?.academy?.level || 1;
  const trainLvl = state.infrastructure?.training?.level || 1;

  for(const p of state.youthAcademy){
    p.age = clamp(Number(p.age) || 16, 15, 18);
    const pot = p.potential || (playerOverall(p) + 8);
    const ovr = playerOverall(p);
    if(ovr < pot){
      const chance = 18 + acadLvl * 6 + trainLvl * 2;
      if((hashStr(playerKey(p) + '|' + state.round) % 100) < chance){
        p.fc = clamp(ovr + 1, 45, pot);
        p.pes = p.fc;
        p.value = calcValueMi(p);
      }
    }
    p.fitness = 100;
    p.morale = clamp((p.morale || 75) + rnd(1, 3), 60, 100);
  }
}


function parkingSpots(lvl){
  const table = [0, 600, 1800, 4000, 8000, 14000];
  return table[lvl] || (lvl * 2500);
}

function recommendedTicketPrice(){const c=clubByName(state?.club);return Math.round(clamp(18+(strength(c)-58)*1.7,15,130))}
function formationSlots(){return FORMATIONS[state?.formation]||FORMATIONS['4-3-3']}

// =========================================================================
// MATRIZ DE APTIDÃO TÁTICA (getPositionFit) — AFM MANAGER 2027
// =========================================================================
function getPositionFit(playerRole, slotRole){
  if(!playerRole || !slotRole) return 'INCOMPATÍVEL';
  const p = String(playerRole).split(',')[0].trim().toUpperCase();
  const s = String(slotRole).trim().toUpperCase();

  // NOTA: Goleiro (GK) NUNCA é adaptado em posição de linha e vice-versa.
  if(p === 'GK' || s === 'GK'){
    return (p === 'GK' && s === 'GK') ? 'IDEAL' : 'INCOMPATÍVEL';
  }

  // 1. 'IDEAL' (Posição de Origem): Exata mesma posição
  if(p === s) return 'IDEAL';

  // 2. 'ADAPTADA' (Posição Secundária / Compatível):
  const adaptedMap = {
    // Zagueiro (CB) em Lateral (LB/RB) ou Volante (DM)
    CB: ['LB', 'RB', 'DM'],
    // Lateral (LB/RB) em Ponta (LW/RW) ou Meia Aberto (LM/RM) ou outro lado
    LB: ['RB', 'LW', 'LM', 'CB'],
    RB: ['LB', 'RW', 'RM', 'CB'],
    // Volante (DM) em Zagueiro (CB) ou Meia Central (CM)
    DM: ['CB', 'CM'],
    // Meia Central (CM) em Volante (DM) ou Meia Armador (AM)
    CM: ['DM', 'AM', 'LM', 'RM'],
    // Meia Armador (AM) em Ponta (LW/RW) ou Meia Central (CM)
    AM: ['LW', 'RW', 'CM', 'CF'],
    // Ponta (LW/RW) em Segundo Atacante / Meia Aberto / Centroavante
    LW: ['RW', 'LM', 'AM', 'ST', 'CF'],
    RW: ['LW', 'RM', 'AM', 'ST', 'CF'],
    // Meias abertos (LM/RM)
    LM: ['LW', 'LB', 'CM', 'AM', 'RM'],
    RM: ['RW', 'RB', 'CM', 'AM', 'LM'],
    // Centroavante (ST/CF) em Segundo Atacante / Ponta
    ST: ['CF', 'LW', 'RW', 'AM'],
    CF: ['ST', 'LW', 'RW', 'AM']
  };

  if(adaptedMap[p]?.includes(s) || adaptedMap[s]?.includes(p)){
    return 'ADAPTADA';
  }

  return 'INCOMPATÍVEL';
}
window.getPositionFit = getPositionFit;

function compatibleScore(p, role){
  const pPos = String(p?.pos || '').trim().toUpperCase();
  const sRole = String(role || '').trim().toUpperCase();
  if(!pPos || !sRole || pPos === sRole) return 0;

  // Goleiro na linha ou jogador de linha no gol: penalidade controlada (-8)
  if(sRole === 'GK' && pPos !== 'GK') return -8;
  if(sRole !== 'GK' && pPos === 'GK') return -8;

  const fit = getPositionFit(pPos, sRole);
  if(fit === 'IDEAL' || fit === 'best') return 0;
  if(fit === 'ADAPTADA' || fit === 'ok') return -3;
  return -6; // Posição fora da origem cai um pouco (-6)
}

function getPlayerEffectiveOverall(p, role){
  const base = typeof playerOverall === 'function' ? playerOverall(p) : (p?.overall || 60);
  if(!p || !role) return base;
  const penalty = compatibleScore(p, role);
  return Math.max(45, Math.min(99, base + penalty));
}
window.getPlayerEffectiveOverall = getPlayerEffectiveOverall;
window.compatibleScore = compatibleScore;

// =========================================================================
// RENDERIZAÇÃO DO CAMPO VERTICAL FIXO (renderVerticalTacticsPitch)
// =========================================================================
function renderVerticalTacticsPitch(starters, formationName = '4-3-3', opts = {}){
  const formSlots = FORMATIONS[formationName] || FORMATIONS['4-3-3'];
  const isHalftime = !!opts.isHalftime;
  const selectedKey = opts.selectedStarterKey || null;

  return `
    <div class="pitch-lines">
      <div class="pitch-half-line"></div>
      <div class="pitch-center-circle"></div>
      <div class="pitch-penalty-top"></div>
      <div class="pitch-penalty-bottom"></div>
    </div>
    ${formSlots.map((slot, idx) => {
      const p = starters[idx] || null;
      const pk = p ? (opts.isHalftime && p.key ? p.key : (typeof playerKey === 'function' ? playerKey(p) : (p.id || p.name))) : '';
      const isSelected = selectedKey && pk && (selectedKey === pk);
      const slotRole = slot.r || (p?.pos || 'ST');
      const posX = slot.x;
      const posY = slot.y;

      return `
        <div class="pitch-slot-dropzone ${isSelected ? 'selected' : ''}"
             id="pitchSlot_${idx}"
             style="left:${posX}%;top:${posY}%;"
             data-slot-index="${idx}"
             data-slot-role="${esc(slotRole)}"
             data-player-key="${esc(pk)}"
             title="${p ? `${esc(p.name)} (${esc(p.pos)})` : 'Slot Vazio'}">
          ${renderFifaMiniCard(p, { index: idx, role: slotRole, x: 50, y: 50 }, {
            isSelected: isSelected,
            isHalftime: isHalftime,
            customClass: 'slot-card-inner'
          })}
        </div>
      `;
    }).join('')}
  `;
}
window.renderVerticalTacticsPitch = renderVerticalTacticsPitch;

// =========================================================================
// MANIPULADORES DE EVENTO DE ARRASTE E CLIQUE (setupTacticsInteractions)
// =========================================================================
function setupTacticsInteractions({ containerEl, starters, bench, onSwap, onStarterSwap, isHalftime }){
  if(!containerEl) return;

  const keyOf = p => isHalftime && p?.key ? p.key : (typeof playerKey === 'function' ? playerKey(p) : p?.key);

  let selectedStarterKey = null;
  let selectedStarterIndex = null;
  let selectedBenchKey = null;

  function clearVisualHighlights(){
    if(window.__afmDragState) window.__afmDragState = { starterKey: null, benchKey: null };
    const slots = containerEl.querySelectorAll('.pitch-slot-dropzone');
    slots.forEach(s => {
      s.classList.remove('selected', 'slot-ideal', 'slot-adapted', 'slot-incompatible', 'slot-dimmed', 'drag-over', 'drag-target');
    });
    const benchRows = containerEl.querySelectorAll('.bench-player-row');
    benchRows.forEach(b => {
      b.classList.remove('selected', 'bench-ideal', 'bench-adapted', 'bench-incompatible', 'drag-over', 'drag-target');
      b.style.borderColor = '';
      b.style.boxShadow = '';
      b.style.background = '';
      b.style.opacity = '1';
    });
  }

  function highlightSlotsForBench(playerPos){
    if(!playerPos) return;
    const slots = containerEl.querySelectorAll('.pitch-slot-dropzone');
    slots.forEach(slot => {
      const slotRole = slot.dataset.slotRole;
      const fit = (typeof getPositionFit === 'function') ? getPositionFit(playerPos, slotRole) : 'IDEAL';
      slot.classList.remove('slot-ideal', 'slot-adapted', 'slot-incompatible', 'slot-dimmed');
      if(fit === 'IDEAL'){
        slot.classList.add('slot-ideal');
      } else if(fit === 'ADAPTADA'){
        slot.classList.add('slot-adapted');
      } else {
        slot.classList.add('slot-incompatible');
      }
    });
  }

  function highlightBenchForStarter(slotRole){
    if(!slotRole) return;
    const benchRows = containerEl.querySelectorAll('.bench-player-row');
    benchRows.forEach(row => {
      const pPos = row.dataset.playerPos;
      const fit = (typeof getPositionFit === 'function') ? getPositionFit(pPos, slotRole) : 'IDEAL';
      row.classList.remove('bench-ideal', 'bench-adapted', 'bench-incompatible');
      if(fit === 'IDEAL'){
        row.classList.add('bench-ideal');
        row.style.borderColor = 'rgba(34, 197, 94, 0.6)';
      } else if(fit === 'ADAPTADA'){
        row.classList.add('bench-adapted');
        row.style.borderColor = 'rgba(234, 179, 8, 0.6)';
      } else {
        row.classList.add('bench-incompatible');
        row.style.borderColor = 'rgba(239, 68, 68, 0.4)';
      }
    });
  }

  // 1. Configurar Slots do Campo (Interação 100% por Clique)
  const slots = containerEl.querySelectorAll('.pitch-slot-dropzone');
  slots.forEach(slot => {
    slot.removeAttribute('draggable');
    slot.ondragenter = null;
    slot.ondragover = null;
    slot.ondragleave = null;
    slot.ondrop = null;
    slot.ondragstart = null;
    slot.ondragend = null;

    slot.onclick = (e) => {
      e.stopPropagation();
      const sKey = slot.dataset.playerKey || '';
      const slotIndex = Number(slot.dataset.slotIndex);

      // CASO A: Reserva já estava selecionado -> Substituição imediata (Reserva ➔ Titular)!
      if(selectedBenchKey){
        const bKey = selectedBenchKey;
        selectedBenchKey = null;
        selectedStarterKey = null;
        selectedStarterIndex = null;
        clearVisualHighlights();
        if(typeof onSwap === 'function'){
          onSwap(sKey, bKey, slotIndex);
        }
        return;
      }

      // CASO B: Outro titular já estava selecionado -> Inverte posições entre titulares!
      if(Number.isInteger(selectedStarterIndex) && selectedStarterIndex !== slotIndex){
        const prevKey = selectedStarterKey;
        const prevIdx = selectedStarterIndex;
        selectedStarterKey = null;
        selectedStarterIndex = null;
        clearVisualHighlights();
        if(typeof onStarterSwap === 'function'){
          onStarterSwap(prevKey, sKey, prevIdx, slotIndex);
        }
        return;
      }

      // CASO C: Mesmo titular clicado novamente -> Desseleciona!
      if(Number.isInteger(selectedStarterIndex) && selectedStarterIndex === slotIndex){
        selectedStarterKey = null;
        selectedStarterIndex = null;
        clearVisualHighlights();
        return;
      }

      // CASO D: Seleciona este titular
      selectedStarterKey = sKey;
      selectedStarterIndex = slotIndex;
      selectedBenchKey = null;
      clearVisualHighlights();
      slot.classList.add('selected');

      const slotRole = slot.dataset.slotRole || 'ST';
      highlightBenchForStarter(slotRole);

      const stPlayer = (starters || []).find((p, idx) => idx === slotIndex || keyOf(p) === sKey);
      toast(`👉 Titular selecionado: ${stPlayer?.name || 'Posição ' + (slotIndex + 1)} (${slotRole}). Clique em um reserva para trocar ou em outro titular para inverter.`);
    };
  });

  // 2. Configurar Linhas do Banco de Reservas (Interação 100% por Clique)
  const benchRows = containerEl.querySelectorAll('.bench-player-row');
  benchRows.forEach(row => {
    row.removeAttribute('draggable');
    row.ondragstart = null;
    row.ondragend = null;
    row.ondragenter = null;
    row.ondragover = null;
    row.ondragleave = null;
    row.ondrop = null;

    row.onclick = (e) => {
      e.stopPropagation();
      const bKey = row.dataset.benchKey;
      const bPos = row.dataset.playerPos;

      // CASO A: Titular já estava selecionado no campo -> Substituição imediata (Titular ➔ Reserva)!
      if(Number.isInteger(selectedStarterIndex) || selectedStarterKey){
        const sKey = selectedStarterKey;
        const targetSlotIndex = selectedStarterIndex;
        selectedStarterKey = null;
        selectedStarterIndex = null;
        selectedBenchKey = null;
        clearVisualHighlights();
        if(typeof onSwap === 'function'){
          onSwap(sKey, bKey, targetSlotIndex);
        }
        return;
      }

      // CASO B: Mesmo reserva clicado novamente -> Desseleciona!
      if(selectedBenchKey === bKey){
        selectedBenchKey = null;
        clearVisualHighlights();
        return;
      }

      // CASO C: Seleciona este reserva
      selectedBenchKey = bKey;
      selectedStarterKey = null;
      selectedStarterIndex = null;
      clearVisualHighlights();

      row.classList.add('selected');
      row.style.borderColor = '#fbbf24';
      row.style.boxShadow = '0 0 16px rgba(250, 204, 21, 0.7)';
      row.style.background = 'rgba(250, 204, 21, 0.15)';

      highlightSlotsForBench(bPos);

      const bPlayer = (bench || []).find(p => keyOf(p) === bKey);
      toast(`👉 Reserva selecionado: ${bPlayer?.name || 'Jogador'} (${bPos}). Clique em qualquer vaga no campo para confirmar a troca.`);
    };
  });

  // Clique no container desmarca seleção se não for em slot/linha
  containerEl.onclick = (e) => {
    if(e.target.closest('.pitch-slot-dropzone') || e.target.closest('.bench-player-row')) return;
    selectedStarterKey = null;
    selectedStarterIndex = null;
    selectedBenchKey = null;
    clearVisualHighlights();
  };
}
window.setupTacticsInteractions = setupTacticsInteractions;

// =========================================================================
// ESCALAÇÃO INTELIGENTE (autoPickBestLineup) — AFM 2027
// =========================================================================
function autoPickBestLineup(squad, formationName = state?.formation || '4-3-3'){
  if (!Array.isArray(squad) || squad.length === 0) return [];
  const form = FORMATIONS[formationName] || FORMATIONS['4-3-3'];
  const available = [...squad];
  const chosenKeys = new Array(form.length).fill(null);

  // Mapeamento rígido de preferências por posição tática
  const rolePreferences = {
    GK: { primary: ['GK'], secondary: [] },
    CB: { primary: ['CB'], secondary: ['RB', 'LB', 'DM'] },
    LB: { primary: ['LB'], secondary: ['LWB', 'RB', 'LM', 'CB'] },
    RB: { primary: ['RB'], secondary: ['RWB', 'LB', 'RM', 'CB'] },
    LWB: { primary: ['LB', 'LWB'], secondary: ['LM', 'RB'] },
    RWB: { primary: ['RB', 'RWB'], secondary: ['RM', 'LB'] },
    DM: { primary: ['DM'], secondary: ['CM', 'CB'] },
    CM: { primary: ['CM'], secondary: ['DM', 'AM'] },
    AM: { primary: ['AM'], secondary: ['CM', 'RW', 'LW', 'CF'] },
    LM: { primary: ['LM', 'LW'], secondary: ['LB', 'AM', 'CM'] },
    RM: { primary: ['RM', 'RW'], secondary: ['RB', 'AM', 'CM'] },
    LW: { primary: ['LW', 'LM'], secondary: ['RW', 'ST', 'AM', 'CF'] },
    RW: { primary: ['RW', 'RM'], secondary: ['LW', 'ST', 'AM', 'CF'] },
    ST: { primary: ['ST', 'CF'], secondary: ['RW', 'LW', 'AM'] },
    CF: { primary: ['CF', 'ST'], secondary: ['AM', 'RW', 'LW'] }
  };

  // 1. PRIMEIRA PASSAGEM: Goleiro (REGRA INVIOLÁVEL: apenas goleiro no gol se houver)
  const gkIndex = form.findIndex(slot => slot.r === 'GK');
  if (gkIndex !== -1) {
    const gks = available.filter(p => (p.pos === 'GK') && (!p.suspended || p.suspended <= 0) && (!p.injury));
    const poolGK = gks.length ? gks : available.filter(p => p.pos === 'GK');
    if (poolGK.length) {
      poolGK.sort((a, b) => playerOverall(b) - playerOverall(a));
      const chosenGK = poolGK[0];
      chosenKeys[gkIndex] = playerKey(chosenGK);
      const rmIdx = available.indexOf(chosenGK);
      if (rmIdx !== -1) available.splice(rmIdx, 1);
    }
  }

  // 2. SEGUNDA PASSAGEM: Posições de ofício estritas (Primary Match)
  const priorityOrder = ['LB', 'RB', 'LWB', 'RWB', 'CB', 'ST', 'CF', 'LW', 'RW', 'LM', 'RM', 'DM', 'AM', 'CM'];
  const slotIndices = form.map((slot, idx) => ({ idx, role: slot.r }))
    .filter(item => item.role !== 'GK');

  slotIndices.sort((a, b) => {
    const prioA = priorityOrder.indexOf(a.role);
    const prioB = priorityOrder.indexOf(b.role);
    return (prioA === -1 ? 99 : prioA) - (prioB === -1 ? 99 : prioB);
  });

  for (const { idx, role } of slotIndices) {
    if (chosenKeys[idx]) continue;
    const pref = rolePreferences[role] || { primary: [role], secondary: [] };
    
    // Candidatos aptos (sem suspensão/lesão grave primeiro)
    const candidates = available.filter(p => {
      if (p.pos === 'GK') return false; // NUNCA colocar goleiro na linha
      return pref.primary.includes(p.pos);
    });

    if (candidates.length) {
      candidates.sort((a, b) => {
        const fitA = (a.fitness ?? 100) / 100;
        const fitB = (b.fitness ?? 100) / 100;
        const scoreA = playerOverall(a) * fitA;
        const scoreB = playerOverall(b) * fitB;
        return scoreB - scoreA;
      });
      const best = candidates[0];
      chosenKeys[idx] = playerKey(best);
      const rmIdx = available.indexOf(best);
      if (rmIdx !== -1) available.splice(rmIdx, 1);
    }
  }

  // 3. TERCEIRA PASSAGEM: Posições secundárias adaptadas (Secondary Match)
  for (const { idx, role } of slotIndices) {
    if (chosenKeys[idx]) continue;
    const pref = rolePreferences[role] || { primary: [role], secondary: [] };
    
    const candidates = available.filter(p => {
      if (p.pos === 'GK') return false;
      return pref.secondary.includes(p.pos);
    });

    if (candidates.length) {
      candidates.sort((a, b) => playerOverall(b) - playerOverall(a));
      const best = candidates[0];
      chosenKeys[idx] = playerKey(best);
      const rmIdx = available.indexOf(best);
      if (rmIdx !== -1) available.splice(rmIdx, 1);
    }
  }

  // 4. QUARTA PASSAGEM: Vagas restantes preenchidas pelos melhores atletas restantes (evitando GK na linha)
  for (let i = 0; i < form.length; i++) {
    if (!chosenKeys[i] && available.length) {
      const nonGKs = available.filter(p => p.pos !== 'GK');
      const pool = nonGKs.length ? nonGKs : available;
      pool.sort((a, b) => playerOverall(b) - playerOverall(a));
      const best = pool[0];
      chosenKeys[i] = playerKey(best);
      const rmIdx = available.indexOf(best);
      if (rmIdx !== -1) available.splice(rmIdx, 1);
    }
  }

  return chosenKeys;
}
window.autoPickBestLineup = autoPickBestLineup;

function optimizeLineup(){
  if (!state?.squad || state.squad.length === 0) return;
  state.lineup = autoPickBestLineup(state.squad, state.formation || '4-3-3');
}

function lineupPlayer(i){const k=state.lineup?.[i];return state.squad.find(p=>playerKey(p)===k)}
function lineupSector(){
  const vals={atk:[],mid:[],def:[]};
  formationSlots().forEach((s,i)=>{
    const p=lineupPlayer(i);
    if(p)vals[s.g].push(Math.max(40,playerOverall(p)+compatibleScore(p,s.r)));
  });
  const avg=a=>a.length?Math.round(a.reduce((x,y)=>x+y,0)/a.length):55;
  return {atk:avg(vals.atk),mid:avg(vals.mid),def:avg(vals.def)};
}
function overallSquad(){const x=lineupSector();return Math.round((x.atk+x.mid+x.def)/3)}
function teamStrengthByName(name){if(norm(name)===norm(state.club))return overallSquad();return state.teams.find(t=>norm(t.name)===norm(name))?.strength||strength(clubByName(name)||{atk:66,mid:66,def:66})}

// =========================================================================
// CONFIGURAÇÃO CENTRAL DAS JANELAS DE TRANSFERÊNCIA ANUAIS
// =========================================================================
const TRANSFER_WINDOWS = [
  { startMonth: 1, startDay: 1, endMonth: 3, endDay: 1, name: 'Janela de Início de Temporada' },
  { startMonth: 6, startDay: 1, endMonth: 8, endDay: 1, name: 'Janela de Meio de Temporada' }
];

function isTransferWindowOpen(dateStr){
  if(state?.freeTransferWindow) return true;
  if(!dateStr) return true;
  const parts = String(dateStr).split('-');
  if(parts.length < 3) return true;
  const m = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  // Janela 1: 01/01 a 01/03 (inclusive)
  if((m === 1) || (m === 2) || (m === 3 && day <= 1)){
    return true;
  }
  // Janela 2: 01/06 a 01/08 (inclusive)
  if((m === 6) || (m === 7) || (m === 8 && day <= 1)){
    return true;
  }
  return false;
}

function getTransferWindowInfo(dateStr){
  if(state?.freeTransferWindow) {
    return { open: true, text: 'Janela Aberta (Modo Livre)', nextOpenDate: 'Sempre Aberto', currentWindow: 'Livre' };
  }
  const parts = String(dateStr || '2026-01-01').split('-');
  const m = parseInt(parts[1], 10) || 1;
  const day = parseInt(parts[2], 10) || 1;
  const open = isTransferWindowOpen(dateStr);

  if(open){
    if(m <= 3){
      return { open: true, text: 'Janela Aberta (fecha em 01/03)', nextOpenDate: '01/06', currentWindow: 'Início de Temporada' };
    }
    return { open: true, text: 'Janela Aberta (fecha em 01/08)', nextOpenDate: '01/01', currentWindow: 'Meio de Temporada' };
  } else {
    // Fora da janela: 02/03 -> 31/05 ou 02/08 -> 31/12
    if(m < 6 || (m === 3 && day > 1)){
      return { open: false, text: 'Janela Fechada (reabre em 01/06)', nextOpenDate: '01/06', currentWindow: null };
    }
    return { open: false, text: 'Janela Fechada (reabre em 01/01)', nextOpenDate: '01/01', currentWindow: null };
  }
}

function teamFameScore(){
  if(!state) return 50;
  let score = 40;
  // Títulos dão enorme prestígio (+12 pts cada)
  score += (state.titles || []).length * 12;
  // Confiança da torcida
  score += ((state.trust?.fans || 70) - 50) * 0.35;
  // Sócios torcedores
  const members = state.socioTorcedor?.members || 1200;
  score += clamp(Math.round(members / 1500), 0, 25);
  // Nível do Departamento de Marketing
  const mktLvl = state.infrastructure?.marketing?.level || 1;
  score += (mktLvl - 1) * 3;
  // Força do elenco e divisão
  const ovr = overallSquad();
  score += clamp((ovr - 60) * 1.2, 0, 25);
  return clamp(Math.round(score), 25, 100);
}

function generateSponsorOffers(clubBudget){
  const fame = teamFameScore();
  const mktLvl = state?.infrastructure?.marketing?.level || 1;
  const mktInvest = Math.max(2500, Number(state?.marketingWeekly) || 12000);
  const mktMult = 1 + (0.03 * (mktLvl - 1)) + clamp((mktInvest - 2500) / 90000, 0, 0.15);
  const fameMult = 0.60 + (fame / 100) * 0.90; // Escala proporcional à fama da equipe
  const seasonFactor = Math.max(0.1, Number(state?.sponsorSeasonFactor) || 1);
  const baseMonthly = Math.round(Math.max(40000, Math.round((clubBudget || 2000000) * 0.024)) * mktMult * fameMult * seasonFactor);

  const sponsorPool = [
    { brand: 'Betano', category: 'Master', color:'#f35b04', mult: 1.45, winMult: 0.22, minFame: 40, years: 1, desc: 'Maior operadora oficial do futebol brasileiro' },
    { brand: 'Samsung', category: 'Master', color:'#1428a0', mult: 1.30, winMult: 0.16, minFame: 55, years: 3, desc: 'Contrato longo e estável com a multinacional' },
    { brand: 'iFood', category: 'Master', color:'#ea1d2c', mult: 1.35, winMult: 0.20, minFame: 30, years: 2, desc: 'Líder nacional de delivery com bônus por vitórias' },
    { brand: 'Superbet', category: 'Master', color:'#dc2626', mult: 1.50, winMult: 0.25, minFame: 50, years: 2, desc: 'Patrocinador master agressivo com altos bônus de vitória' },
    { brand: 'Nubank', category: 'Master', color:'#820ad1', mult: 1.40, winMult: 0.18, minFame: 65, years: 2, desc: 'Fintech global com forte apelo entre a torcida jovem' },
    { brand: 'Emirates', category: 'Master', color:'#d97706', mult: 1.70, winMult: 0.28, minFame: 80, years: 3, desc: 'Gigante aérea mundial com investimento milionário' },
    
    { brand: 'Fatal Model', category: 'Mangas', color:'#6b21a8', mult: 0.60, winMult: 0.09, minFame: 25, years: 1, desc: 'Patrocínio de mangas com investimento pontual' },
    { brand: 'GOL Linhas Aéreas', category: 'Mangas', color:'#ff7020', mult: 0.65, winMult: 0.10, minFame: 45, years: 2, desc: 'Apoio logístico e mensalidade garantida' },
    { brand: 'Cimed', category: 'Mangas', color:'#facc15', mult: 0.70, winMult: 0.12, minFame: 55, years: 2, desc: 'Indústria farmacêutica nacional nas mangas da camisa' },
    { brand: 'EstrelaBet', category: 'Mangas', color:'#0284c7', mult: 0.68, winMult: 0.11, minFame: 35, years: 1, desc: 'Investimento fixo nas mangas e premiação imediata' },
    
    { brand: 'BYD', category: 'Costas', color:'#009e60', mult: 0.55, winMult: 0.08, minFame: 30, years: 2, desc: 'Marca tecnológica sustentável na omoplata do manto' },
    { brand: 'Brahma', category: 'Costas', color:'#b91c1c', mult: 0.60, winMult: 0.09, minFame: 50, years: 2, desc: 'Tradição brasileira no verso do uniforme' },
    { brand: 'Itaú', category: 'Costas', color:'#ea580c', mult: 0.65, winMult: 0.10, minFame: 65, years: 3, desc: 'Maior banco privado com solidez garantida' },
    { brand: 'Zé Delivery', category: 'Costas', color:'#eab308', mult: 0.52, winMult: 0.08, minFame: 35, years: 1, desc: 'Ativação de torcida nas costas da camisa' }
  ];

  // Filtra marcas elegíveis para a fama atual do time e sorteia 3 a 4 propostas
  const eligible = sponsorPool.filter(s => fame >= s.minFame);
  const shuffled = [...(eligible.length >= 3 ? eligible : sponsorPool)].sort(() => Math.random() - 0.5);
  const selected = shuffled.slice(0, 4);

  return selected.map(s => ({
    brand: s.brand,
    category: s.category,
    color: s.color,
    monthly: Math.round(baseMonthly * s.mult),
    winBonus: Math.round(baseMonthly * s.winMult),
    years: s.years,
    desc: s.desc
  }));
}

function checkNewSponsorOffer(){
  if(!state) return;
  state.sponsorOffers = state.sponsorOffers || [];
  if(state.sponsorOffers.length >= 5) return; // Limite de 5 propostas ativas

  const fresh = generateSponsorOffers(state.balance);
  const newOffer = fresh.find(f => !state.sponsorOffers.some(o => o.brand === f.brand) && (!state.sponsors || !Object.values(state.sponsors).some(sp => sp?.brand === f.brand)));
  if(newOffer){
    state.sponsorOffers.unshift(newOffer);
    state.news.unshift(`📬 NOVA PROPOSTA DE PATROCÍNIO: A empresa ${newOffer.brand} enviou oferta para estampar o espaço ${newOffer.category} (${fmtMoney(newOffer.monthly)}/mês)! Fama do clube: ${teamFameScore()}%`);
    toast(`📬 Nova proposta de patrocínio recebida: ${newOffer.brand} (${newOffer.category})!`);
  }
}

function signSponsorOffer(idx){
  const offer = state.sponsorOffers[idx];
  if(!offer) return;

  const slotKey = offer.category === 'Master' ? 'master' : offer.category === 'Mangas' ? 'sleeves' : 'back';
  const current = state.sponsors ? state.sponsors[slotKey] : null;

  if(current && current.brand && current.brand !== 'Sem Patrocínio'){
      // Multa proporcional ao compromisso contratual restante e à importância do espaço.
      // Master: 20%; Mangas: 15%; Costas/Omoplata: 10% do valor contratual restante.
      const breakPenaltyRate = slotKey === 'master' ? 0.20 : slotKey === 'sleeves' ? 0.15 : 0.10;
      const currentMonthly = Math.max(0, Number(current.monthly) || 50000);
      const contractYears = Math.max(1, Number(current.years) || Number(current.contractYears) || 1);
      const totalContractValue = currentMonthly * 12 * contractYears;
      const monthsRemaining = Math.max(1, Math.min(contractYears * 12,
        Number(current.monthsRemaining ?? current.remainingMonths ?? current.contractMonthsRemaining) || contractYears * 12));
      const remainingContractValue = Math.round(currentMonthly * monthsRemaining);
      const breakFee = Math.max(1, Math.round(remainingContractValue * breakPenaltyRate));
    const canAfford = state.balance >= breakFee;

    openCustomModal(
      '⚠️ Quebra de Contrato de Patrocínio',
      `
        <div style="background:rgba(239,68,68,0.1);border:1px solid #ef4444;border-radius:12px;padding:16px;margin-bottom:14px">
          <div style="font-size:14px;font-weight:900;color:#ef4444;text-transform:uppercase">
            Espaço ${offer.category} Já Ocupado
          </div>
          <div style="font-size:13px;color:rgba(255,255,255,0.8);margin-top:6px;line-height:1.4">
            O seu clube já possui contrato ativo com a empresa <b>${esc(current.brand)}</b> recebendo <b>${fmtMoney(current.monthly)}/mês</b>.
          </div>
        </div>

        <div style="background:#13111c;border:1px solid rgba(255,255,255,0.08);border-radius:12px;padding:16px;font-size:13px">
          <div style="display:flex;justify-content:space-between;margin-bottom:8px">
            <span class="muted">Novo Patrocinador:</span>
            <b style="color:${offer.color}">${esc(offer.brand)} (${fmtMoney(offer.monthly)}/mês)</b>
          </div>
            <div style="display:flex;justify-content:space-between;margin-bottom:8px">
              <span class="muted">Multa Rescisória de Quebra de Contrato:</span>
              <b style="color:#ef4444">${fmtMoney(breakFee)}</b>
            </div>
            <div style="font-size:11px;color:rgba(255,255,255,0.55);margin-bottom:8px;line-height:1.4">
              Base contratual restante: <b>${fmtMoney(remainingContractValue)}</b> de ${fmtMoney(totalContractValue)} · Multa de ${Math.round(breakPenaltyRate * 100)}% para o espaço ${esc(offer.category)}.
            </div>
          <div style="display:flex;justify-content:space-between">
            <span class="muted">Saldo em Caixa do Clube:</span>
            <b style="color:${canAfford?'#22c55e':'#ef4444'}">${fmtMoney(state.balance)}</b>
          </div>
        </div>

        <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:16px">
          <button class="btn" id="btnCancelBreakSponsor">Manter Atual</button>
          <button class="btn danger" id="btnConfirmBreakSponsor" ${canAfford ? '' : 'disabled'} style="font-weight:900;padding:10px 18px">
            ${canAfford ? `Pagar ${fmtMoney(breakFee)} e Trocar Patrocínio` : 'Saldo Insuficiente p/ Multa'}
          </button>
        </div>
      `,
      null,
      'Fechar',
      false,
      '560px'
    );

    const bCancel = $('#btnCancelBreakSponsor');
    if(bCancel) bCancel.onclick = closeCustomModal;

    const bConfirm = $('#btnConfirmBreakSponsor');
    if(bConfirm){
      bConfirm.onclick = () => {
        if(!canAfford) return;
        state.balance -= breakFee;
        state.expense = (state.expense || 0) + breakFee;
        const signingBonus = Math.round((offer.monthly || 50000) * 0.5);
        state.balance += signingBonus;
        state.income = (state.income || 0) + signingBonus;
        state.sponsors[slotKey] = offer;
        state.sponsorOffers.splice(idx, 1);
        state.news.unshift(`🤝 TROCA DE PATROCÍNIO: O ${state.club} pagou ${fmtMoney(breakFee)} de rescisão com a ${current.brand} e recebeu +${fmtMoney(signingBonus)} de luvas da ${offer.brand}!`);
        toast(`🎉 Contrato com a ${offer.brand} assinado (+${fmtMoney(signingBonus)} no caixa)!`);
        closeCustomModal();
        save();
        render();
      };
    }
  } else {
    // Espaço livre, assina direto com luvas!
    state.sponsors = state.sponsors || {};
    state.sponsors[slotKey] = offer;
    state.sponsorOffers.splice(idx, 1);
    const signingBonus = Math.round((offer.monthly || 50000) * 0.5);
    state.balance += signingBonus;
    state.income = (state.income || 0) + signingBonus;
    state.news.unshift(`💰 PATROCÍNIO: O ${state.club} oficializou parceria de ${offer.category} com a ${offer.brand} (+${fmtMoney(signingBonus)} de luvas à vista)!`);
    toast(`🎉 Contrato com a ${offer.brand} assinado (+${fmtMoney(signingBonus)} no caixa)!`);
    save();
    render();
  }
}


function initCandangaoData(season = state?.season || 2026, teamNames = null){
  const teams = Array.isArray(teamNames) && teamNames.length
    ? teamNames
    : ((window.COMPETITION_TEAMS?.['bra-est-df'] || ['Gama','Capital-DF','Sobradinho','Samambaia','Ceilândia','Paranoá','Real Brasília','Brasiliense','ARUC','Brasília']).slice());
  const firstRoundDate = getDateForRound(0, season);
  return {
    id: 'bra-est-df', name: 'Campeonato Candango', season: Number(season) || 2026,
    phase: 'primeira', currentRound: 1,
    roundDate: formatDatePtBr(firstRoundDate).toUpperCase(),
    teams: teams.map(name => ({ name, p:0, j:0, v:0, e:0, d:0, gp:0, gc:0, sg:0, pct:0, form:[] })),
    fixtures: (roundRobin(teams)[0] || []).map(([home, away]) => {
      const homeClub = clubByName(home) || {};
      return { stadium: homeClub.stadium || `Estádio do ${home}`, isoDate:firstRoundDate,
        dateStr:`${formatDatePtBr(firstRoundDate)} · 19:00`, home, away };
    })
  };
}
function initCandangaoStats(){ return { scorers: [], assists: [] }; }

function getStateCompData(cId){
  state.estadualData = state.estadualData || {};
  const saved = state.estadualData[cId];
  if(saved && Number(saved.season) !== Number(state.season)){
    const hasSavedResults = (saved.teams || []).some(team => Number(team.j) > 0) || (saved.fixtures || []).some(fixture => fixture.result || fixture.score || fixture.played);
    if(hasSavedResults){
      state.estadualArchive = state.estadualArchive || {};
      state.estadualArchive[cId] = Array.isArray(state.estadualArchive[cId]) ? state.estadualArchive[cId] : [];
      if(!state.estadualArchive[cId].some(item => Number(item.season) === Number(saved.season))) state.estadualArchive[cId].push(clone(saved));
    }
    delete state.estadualData[cId];
  }
  const currentSaved = state.estadualData[cId];
  const comp = compById(cId) || {id:cId,name:'Campeonato Estadual'};
  const catalogRoster = (typeof BASE_COMPETITION_TEAMS !== 'undefined' ? BASE_COMPETITION_TEAMS?.[cId] : null) || window.COMPETITION_TEAMS?.[cId] || [];
  const savedRoster = state.competitionTeams?.[cId] || [];
  const clubForState = state.club && clubStateCompId(state.club) === cId ? state.club : null;
  // Reconcile old saves with the complete roster: a stale one-round fixture list must not blank the official calendar.
  // Prefer the active save's roster so career-only entrants and prior season
  // promotions stay local; the static catalog is just the fallback baseline.
  const rosterSource = savedRoster.length ? savedRoster : catalogRoster;
  const roster = rosterSource.map(team => typeof team === 'string' ? team : team?.name).filter(Boolean);
  if(clubForState && !roster.some(name => norm(name) === norm(clubForState))) roster.push(clubForState);
  const teams = roster.filter((name,index,list)=>list.findIndex(other=>norm(other)===norm(name))===index);
  const stateRounds = roundRobin(teams);
  const roundDates = stateRounds.map((_, roundIndex) => getDateForRound(roundIndex, state.season));
  const previousFixtures = Array.isArray(currentSaved?.fixtures) ? currentSaved.fixtures : [];
  const archivedHistory = (state.history || []).filter(item => (item?.competitionId === cId || (!item?.competitionId && norm(item.competitionName) === norm(comp.name))) && Number(item.season || state.season) === Number(state.season));
  const usedPreviousFixtures = new Set();
  const fixtures = stateRounds.flatMap((games, roundIndex) => games.map(([home,away]) => {
    let previousIndex = previousFixtures.findIndex((f,index) => !usedPreviousFixtures.has(index) && norm(f.home)===norm(home) && norm(f.away)===norm(away) && Number(f.roundIndex)===roundIndex);
    if(previousIndex < 0) previousIndex = previousFixtures.findIndex((f,index) => !usedPreviousFixtures.has(index) && norm(f.home)===norm(home) && norm(f.away)===norm(away));
    const previous = previousIndex >= 0 ? previousFixtures[previousIndex] : null;
    if(previousIndex >= 0) usedPreviousFixtures.add(previousIndex);
    const history = archivedHistory.find(item => norm(item.h) === norm(home) && norm(item.a) === norm(away) && (!item.date || !previous?.isoDate || item.date === previous.isoDate));
    const isoDate = previous?.isoDate || history?.date || roundDates[roundIndex];
    return {
      stadium:(clubByName(home)||{}).stadium || `Estádio do ${home}`,
      roundIndex, isoDate,
      dateStr:`${formatDatePtBr(isoDate)} · 19:00`, home, away,
      ...(previous?.result ? {result:Array.isArray(previous.result) ? [...previous.result] : previous.result,played:true} : {}),
      ...(previous?.score ? {score:Array.isArray(previous.score) ? [...previous.score] : previous.score,played:true} : {}),
      ...(previous?.played || history ? {played:true} : {}),
      ...(history && !previous?.result && !previous?.score ? {result:[Number(history.hg)||0,Number(history.ag)||0],played:true} : {})
    };
  }));
  const savedTeams = Array.isArray(currentSaved?.teams) ? currentSaved.teams : [];
  const teamStats = teams.map(name => {
    const previous = savedTeams.find(team=>norm(team.name)===norm(name));
    return previous ? {...previous,name} : {name,p:0,j:0,v:0,e:0,d:0,gp:0,gc:0,sg:0,pct:0,form:[]};
  });
  const data = state.estadualData[cId] = {
    ...(currentSaved || {}), id:cId,name:comp.name,season:Number(state.season),
    phase:currentSaved?.phase || 'primeira',currentRound:Math.max(1,Number(currentSaved?.currentRound)||1),
    roundDate:currentSaved?.roundDate || formatDatePtBr(roundDates[0] || getDateForRound(0,state.season)).toUpperCase(),
    teams:teamStats,fixtures
  };
  // Rebuild missing table rows from persisted completed fixtures, only when the save
  // has no table stats, so already-played matches do not disappear on a calendar repair.
  if(!savedTeams.some(team => Number(team.j) > 0)){
    const rebuilt = new Set();
    for(const fixture of fixtures){
      if(!fixture.played || !Array.isArray(fixture.result) || fixture.result.length < 2) continue;
      const identity = `${fixture.roundIndex}|${norm(fixture.home)}|${norm(fixture.away)}`;
      if(rebuilt.has(identity)) continue;
      rebuilt.add(identity);
      const [hg,ag] = fixture.result.map(value=>Math.max(0,Number(value)||0));
      const home = data.teams.find(team=>norm(team.name)===norm(fixture.home));
      const away = data.teams.find(team=>norm(team.name)===norm(fixture.away));
      if(!home || !away) continue;
      home.j++; away.j++; home.gp+=hg; home.gc+=ag; away.gp+=ag; away.gc+=hg;
      if(hg>ag){home.v++;home.p+=3;away.d++;}else if(hg<ag){away.v++;away.p+=3;home.d++;}else{home.e++;away.e++;home.p++;away.p++;}
    }
    data.teams.forEach(team=>{team.sg=team.gp-team.gc;team.pct=team.j?Math.round(team.p/(team.j*3)*100):0;});
  }
  // Persist the full roster only in this career save. Never append career-only clubs
  // to window.COMPETITION_TEAMS, which is shared by every new career/session.
  state.competitionTeams = state.competitionTeams || {};
  state.competitionTeams[cId] = teams.slice();
  return data;
}
function getStateCompStats(cId){
  state.competitionStats = state.competitionStats || {};
  if(state.competitionStats[cId] && (Number(state.competitionStats[cId].season) === Number(state.season) || (!state.competitionStats[cId].season && Number(state.season) === 2026))){
    state.competitionStats[cId].season = Number(state.season);
    return state.competitionStats[cId];
  }
  state.competitionStats[cId] = { season: Number(state.season), scorers: [], assists: [] };
  return state.competitionStats[cId];
}

function addPlayerMatchStats(competitionId, clubName, events){
  if(!clubName || !Array.isArray(events)) return;
  const stats = getStateCompStats(competitionId);
  const add = (list, playerName, key) => {
    if(!playerName) return;
    const player = state.squad?.find(p => norm(p.name) === norm(playerName));
    const row = list.find(item => norm(item.name) === norm(playerName) && norm(item.club) === norm(clubName)) || {
      name: playerName, club: clubName, pos: player?.pos || 'JOGADOR', [key]: 0
    };
    if(!list.includes(row)) list.push(row);
    row[key] = (Number(row[key]) || 0) + 1;
    if(player) player[key] = (Number(player[key]) || 0) + 1;
  };
  events.filter(event => event?.type === 'gol' && norm(event.teamId) === norm(clubName)).forEach(event => {
    add(stats.scorers, event.scorer, 'goals');
    add(stats.assists, event.assist, 'assists');
  });
}

function simulateUserGoalEvents(clubName, goals){
  const eligible = (state.squad || []).filter(player => !/^(GK|GOLEIRO)$/i.test(player.pos || ''));
  return Array.from({length: Math.max(0, Number(goals) || 0)}, (_, index) => {
    if(!eligible.length) return null;
    const scorer = eligible[rnd(0, eligible.length - 1)];
    const helpers = eligible.filter(player => player !== scorer);
    const assist = helpers.length && Math.random() < 0.72 ? helpers[rnd(0, helpers.length - 1)] : null;
    return { type: 'gol', teamId: clubName, scorer: scorer.name, assist: assist?.name || null, min: 8 + index * 19 };
  }).filter(Boolean);
}

