function bindMarketFilters(){
  const reg=$('#marketRegion'), country=$('#marketCountry'), comp=$('#marketComp'), clubSel=$('#marketClub');
  if(!reg) return;

  function updateCountries(){
    const rVal = reg.value;
    const countries = rVal ? regionCountries(rVal) : [...new Set((window.COMPETITIONS||[]).map(c=>c.country))].sort();
    country.innerHTML = '<option value="">Todos os Países</option>' + countries.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');
    updateComps();
  }

  function updateComps(){
    const rVal = reg.value, cVal = country.value;
    const comps = (window.COMPETITIONS||[]).filter(c=>(!rVal||c.continent===rVal)&&(!cVal||c.country===cVal));
    comp.innerHTML = '<option value="">Todos os Campeonatos</option>' + comps.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
    updateClubOptions();
  }

  function updateClubOptions(){
    const cId = comp.value;
    let pool = [];
    if(cId){
      const c = compById(cId);
      pool = eligibleClubNames(c);
    } else if(country.value){
      pool = clubs.filter(x=>x.country===country.value).map(x=>x.name);
    } else if(reg.value){
      const contCountries = regionCountries(reg.value);
      pool = clubs.filter(x=>contCountries.includes(x.country)).map(x=>x.name);
    } else {
      pool = clubs.map(x=>x.name);
    }
    clubSel.innerHTML = '<option value="">Todos os Clubes</option>' + pool.slice(0, 100).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
    renderMarketBuy();
  }

  reg.onchange = updateCountries;
  country.onchange = updateComps;
  comp.onchange = updateClubOptions;
  clubSel.onchange = renderMarketBuy;
  const sortSel = $('#marketSort');
  if(sortSel) sortSel.onchange = renderMarketBuy;
  updateCountries();
}

function renderMarketBuy(){
  const el=$('#buyList') || $('#marketList'); if(!el) return;
  const q=norm($('#marketQ')?.value), pos=$('#marketPos')?.value||'', min=+($('#marketMin')?.value||0), aff=$('#onlyAffordable')?.checked;
  const regVal = $('#marketRegion')?.value;
  const countryVal = $('#marketCountry')?.value;
  const compVal = $('#marketComp')?.value;
  const clubVal = $('#marketClub')?.value;
  const windowOpen = isTransferWindowOpen(state.date);
  const sortMode = $('#marketSort')?.value || 'recommended';

  let compClubSet = null;
  if(compVal){
    const c = compById(compVal);
    if(c) compClubSet = new Set(eligibleClubNames(c).map(norm));
  }

  const clubValNorm = clubVal ? norm(clubVal) : '';
  const countryValNorm = countryVal ? norm(countryVal) : '';
  const regCountriesSet = regVal ? new Set(regionCountries(regVal)) : null;

  let ps=marketUniverse().filter(p=>{
    if(q && !(p.searchStr || '').includes(q)) return false;
    if(pos && String(p.pos||'').split(',')[0].trim()!==pos) return false;
    const ovr = p.ovr != null ? p.ovr : playerOverall(p);
    if(ovr < min) return false;
    const val = p.value != null ? p.value : calcValueMi(p);
    if(aff && val*1e6 > state.balance) return false;
    if(clubValNorm && (p.clubNorm || norm(p.club)) !== clubValNorm) return false;
    if(compClubSet && !compClubSet.has(p.clubNorm || norm(p.club))) return false;
    
    if(countryValNorm && (p.countryNorm || norm(p.country)) !== countryValNorm) return false;
    if(regCountriesSet && !regCountriesSet.has(p.country)) return false;
    return true;
  });

  // Pipeline de ordenação estável ultra-rápida (usa valores pré-computados)
  ps.sort((a,b) => {
    const ovrA = a.ovr != null ? a.ovr : playerOverall(a);
    const ovrB = b.ovr != null ? b.ovr : playerOverall(b);
    const valA = a.value != null ? a.value : calcValueMi(a);
    const valB = b.value != null ? b.value : calcValueMi(b);
    const ageA = a.age || 25, ageB = b.age || 25;
    const nameA = a.name || '', nameB = b.name || '';
    const idA = a.id || a.marketKey || '', idB = b.id || b.marketKey || '';

    let diff = 0;
    switch(sortMode){
      case 'name_asc': diff = (nameA > nameB ? 1 : (nameA < nameB ? -1 : 0)); break;
      case 'name_desc': diff = (nameB > nameA ? 1 : (nameB < nameA ? -1 : 0)); break;
      case 'age_asc': diff = ageA - ageB; break;
      case 'age_desc': diff = ageB - ageA; break;
      case 'price_asc': diff = valA - valB; break;
      case 'price_desc': diff = valB - valA; break;
      case 'ovr_asc': diff = ovrA - ovrB; break;
      case 'ovr_desc': diff = ovrB - ovrA; break;
      default: // recommended
        diff = (ovrB - ovrA) || (valB - valA); break;
    }
    return diff || (nameA > nameB ? 1 : (nameA < nameB ? -1 : 0)) || (idA > idB ? 1 : (idA < idB ? -1 : 0));
  });

  ps = ps.slice(0, 100);

  if(!ps.length){ el.innerHTML='<div class="empty">Nenhum jogador encontrado com esses filtros selecionados.</div>'; return; }

  el.innerHTML=`
    <div class="tablewrap card">
      <table>
        <thead><tr><th>Jogador</th><th>Clube</th><th>Pos</th><th>Overall</th><th>Idade</th><th>Valor de Mercado</th><th>Ação</th></tr></thead>
        <tbody>
          ${ps.map(p=>{
            const val = p.value != null ? p.value : calcValueMi(p), key = p.marketKey || playerKey(p);
            const canAfford = val*1e6 <= state.balance;
            const canBuy = windowOpen && canAfford;
            const btnText = !windowOpen ? 'Janela Fechada' : (!canAfford ? 'Sem caixa' : 'Comprar');
            const btnTitle = !windowOpen ? 'Mercado de transferências fechado fora da janela' : (!canAfford ? 'Saldo em caixa insuficiente' : 'Iniciar negociação');
            const ovr = p.ovr != null ? p.ovr : playerOverall(p);
            return `
              <tr>
                <td><b>${esc(p.name)}</b></td>
                <td><div class="club-cell">${clubBadge(p.club, 22)} ${esc(p.club||'-')}</div></td>
                <td><span class="pill" style="font-size:11px">${esc(p.pos||'-')}</span></td>
                <td><span class="rating-pill ${ratingClass(ovr)}">${ovr}</span></td>
                <td>${p.age||'-'} anos</td>
                <td><b class="good">${fmtMi(val)}</b></td>
                <td><button class="btn primary buy" data-key="${esc(key)}" title="${esc(btnTitle)}" ${!canBuy?'disabled':''}>${btnText}</button></td>
              </tr>
            `;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;
  $$('.buy').forEach(b=>b.onclick=()=>buyPlayer(b.dataset.key));
}


function bindLoanFilters(){
  const reg=$('#loanRegion'), country=$('#loanCountry'), comp=$('#loanComp'), clubSel=$('#loanClub');
  if(!reg) return;

  function updateCountries(){
    const rVal = reg.value;
    const countries = rVal ? regionCountries(rVal) : [...new Set((window.COMPETITIONS||[]).map(c=>c.country))].sort();
    country.innerHTML = '<option value="">Todos os Países</option>' + countries.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');
    updateComps();
  }

  function updateComps(){
    const rVal = reg.value, cVal = country.value;
    const comps = (window.COMPETITIONS||[]).filter(c=>(!rVal||c.continent===rVal)&&(!cVal||c.country===cVal));
    comp.innerHTML = '<option value="">Todos os Campeonatos</option>' + comps.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
    updateClubOptions();
  }

  function updateClubOptions(){
    const cId = comp.value;
    let pool = [];
    if(cId){
      const c = compById(cId);
      pool = eligibleClubNames(c);
    } else if(country.value){
      pool = clubs.filter(x=>x.country===country.value).map(x=>x.name);
    } else if(reg.value){
      const contCountries = regionCountries(reg.value);
      pool = clubs.filter(x=>contCountries.includes(x.country)).map(x=>x.name);
    } else {
      pool = clubs.map(x=>x.name);
    }
    clubSel.innerHTML = '<option value="">Todos os Clubes</option>' + pool.slice(0, 100).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
    renderMarketLoans();
  }

  reg.onchange = updateCountries;
  country.onchange = updateComps;
  comp.onchange = updateClubOptions;
  clubSel.onchange = renderMarketLoans;
  updateCountries();
}

function renderMarketLoans(){
  try {
    const el = $('#loanList'); if(!el) return;
    const q = norm($('#loanQ')?.value || (typeof loanQFilter !== 'undefined' ? loanQFilter : '') || '');
    const pos = $('#loanPos')?.value || (typeof loanPosFilter !== 'undefined' && loanPosFilter !== 'TODAS' && loanPosFilter !== 'ALL' ? loanPosFilter : '');
    const min = +($('#loanMin')?.value || 0);
  const aff = $('#onlyAffordableLoan')?.checked;
  const regVal = $('#loanRegion')?.value;
  const countryVal = $('#loanCountry')?.value;
  const compVal = $('#loanComp')?.value;
  const clubVal = $('#loanClub')?.value;
  const sortVal = $('#selectLoanOrder')?.value || 'ovr';

  let compClubSet = null;
  if(compVal){
    const c = compById(compVal);
    if(c) compClubSet = new Set(eligibleClubNames(c).map(norm));
  }

    const clubValNorm = clubVal ? norm(clubVal) : '';
    const countryValNorm = countryVal ? norm(countryVal) : '';
    const regCountriesSet = regVal ? new Set(regionCountries(regVal)) : null;

    let pool = marketUniverse().filter(p => {
      const ovr = p.ovr != null ? p.ovr : playerOverall(p);
      if(ovr < 52) return false;
      if(min && ovr < min) return false;

      if(q && !(p.searchStr || '').includes(q)) return false;
      if(pos && String(p.pos||'').split(',')[0].trim() !== pos) return false;

      const val = p.value != null ? p.value : calcValueMi(p);
      const fee = Math.round(val * 1e6 * 0.10);
      if(aff && fee > state.balance) return false;

      if(clubValNorm && (p.clubNorm || norm(p.club)) !== clubValNorm) return false;
      if(compClubSet && !compClubSet.has(p.clubNorm || norm(p.club))) return false;

      if(countryValNorm && (p.countryNorm || norm(p.country)) !== countryValNorm) return false;
      if(regCountriesSet && !regCountriesSet.has(p.country)) return false;
      return true;
    });

    if(sortVal === 'cheap'){
      pool.sort((a,b) => ((a.value != null ? a.value : calcValueMi(a)) - (b.value != null ? b.value : calcValueMi(b))));
    } else if(sortVal === 'age'){
      pool.sort((a,b) => (a.age||22) - (b.age||22));
    } else {
      pool.sort((a,b) => ((b.ovr != null ? b.ovr : playerOverall(b)) - (a.ovr != null ? a.ovr : playerOverall(a))) || ((b.value != null ? b.value : calcValueMi(b)) - (a.value != null ? a.value : calcValueMi(a))));
    }

    const list = pool.slice(0, 100);

  if(!list.length){
    el.innerHTML = '<div class="empty" style="padding:24px;text-align:center">Nenhum jogador encontrado com os filtros selecionados para empréstimo.</div>';
    return;
  }

  el.innerHTML = `
    <div class="tablewrap">
      <table>
        <thead>
          <tr style="font-size:11px;color:rgba(255,255,255,0.5)">
            <th style="width:36px">FOTO</th>
            <th>JOGADOR</th>
            <th>CLUBE</th>
            <th>POS</th>
            <th style="text-align:center">NOTA</th>
            <th style="text-align:center">IDADE</th>
            <th style="text-align:right">TAXA ANUAL</th>
            <th style="text-align:center">AÇÃO</th>
          </tr>
        </thead>
        <tbody>
          ${list.map(p => {
            const fee = Math.round(calcValueMi(p) * 1e6 * 0.10);
            const key = playerKey(p);
            const windowOpen = isTransferWindowOpen(state?.date);
            const canLoan = windowOpen && fee <= state.balance;
            const btnText = !windowOpen ? 'Janela Fechada' : (fee > state.balance ? 'Sem caixa' : 'Negociar Empréstimo');
            const btnTitle = !windowOpen ? 'Mercado de transferências fechado fora da janela' : 'Negociar contratação por empréstimo';

            return `
              <tr>
                <td style="width:36px">${playerPhoto(p, 28)}</td>
                <td><b>${esc(p.name)}</b></td>
                <td><div class="club-cell">${clubBadge(p.club, 18)} ${esc(p.club||'-')}</div></td>
                <td><span class="pill" style="font-size:11px">${esc(p.pos||'-')}</span></td>
                <td style="text-align:center"><span class="rating-pill ${ratingClass(playerOverall(p))}">${playerOverall(p)}</span></td>
                <td style="text-align:center">${p.age||22} anos</td>
                <td style="text-align:right;color:#22c55e;font-weight:800">${fmtMoney(fee)}</td>
                <td style="text-align:center">
                  <button class="btn success loan-in" data-key="${esc(key)}" title="${esc(btnTitle)}" ${!canLoan?'disabled':''} style="padding:4px 14px;font-size:12px;font-weight:800;border-radius:6px;${!canLoan?'background:rgba(255,255,255,0.1);color:rgba(255,255,255,0.4);cursor:not-allowed':'background:#16a34a;color:#fff;cursor:pointer'};border:none">
                    ${btnText}
                  </button>
                </td>
              </tr>
            `;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;

  $$('.loan-in').forEach(b => b.onclick = () => loanInPlayer(b.dataset.key));
  } catch(err) {
    recordAFMError('market-loans-render', err);
    console.error('Erro em renderMarketLoans:', err);
  }
}

