// -------------------------------------------------------------
// -------------------------------------------------------------
// SISTEMA DE SUBSTITUIÇÃO 100% POR CLIQUE (AFM 2027)
// -------------------------------------------------------------
// Shared tactical UI state. myTeamPage() reads tacticalActiveTab while
// building its accordion markup, and bind() updates it on open/close.
// Keep it initialized in the same scope as both callers.
var tacticalActiveTab = 'closed';
var tacticalSelectedKey = null;
window.tacticalSelectedKey = null;

function executeSwap(sourceKey, targetKey, targetSlotIndex = null, sourceSlotIndex = null) {
  if (!sourceKey && !targetKey && !Number.isInteger(targetSlotIndex)) return;
  if (!Array.isArray(state.lineup)) state.lineup = [];

  while (state.lineup.length < 11) {
    state.lineup.push(null);
  }

  // CASO TITULAR ↔ TITULAR: Se ambos os índices de titulares foram passados diretamente
  if (Number.isInteger(sourceSlotIndex) && Number.isInteger(targetSlotIndex) &&
      sourceSlotIndex >= 0 && sourceSlotIndex < 11 &&
      targetSlotIndex >= 0 && targetSlotIndex < 11 &&
      sourceSlotIndex !== targetSlotIndex) {
    const temp = state.lineup[sourceSlotIndex];
    state.lineup[sourceSlotIndex] = state.lineup[targetSlotIndex];
    state.lineup[targetSlotIndex] = temp;
    tacticalSelectedKey = null;
    save();
    render();
    toast('🔄 Posições trocadas com sucesso!');
    return;
  }

  // Normaliza IDs de saves antigos
  state.lineup = state.lineup.map(key => {
    if (!key) return null;
    const player = findSquadPlayerByKey(String(key || ''));
    return player ? playerKey(player) : key;
  });

  const sourcePlayer = sourceKey ? findSquadPlayerByKey(String(sourceKey)) : null;
  const sKey = sourcePlayer ? playerKey(sourcePlayer) : (sourceKey || null);

  const targetPlayer = targetKey ? findSquadPlayerByKey(String(targetKey)) : null;
  const tKey = targetPlayer ? playerKey(targetPlayer) : (targetKey || null);

  let sourceLineupIdx = -1;
  if (Number.isInteger(sourceSlotIndex) && sourceSlotIndex >= 0 && sourceSlotIndex < 11) {
    sourceLineupIdx = sourceSlotIndex;
  } else if (sKey) {
    sourceLineupIdx = state.lineup.findIndex(k => {
      if (!k) return false;
      if (k === sKey || k === sourceKey) return true;
      const p = findSquadPlayerByKey(k);
      return p && (playerKey(p) === sKey || playerKey(p) === sourceKey);
    });
  }

  let targetLineupIdx = -1;
  if (Number.isInteger(targetSlotIndex) && targetSlotIndex >= 0 && targetSlotIndex < 11) {
    targetLineupIdx = targetSlotIndex;
  } else if (tKey) {
    targetLineupIdx = state.lineup.findIndex(k => {
      if (!k) return false;
      if (k === tKey || k === targetKey) return true;
      const p = findSquadPlayerByKey(k);
      return p && (playerKey(p) === tKey || playerKey(p) === targetKey);
    });
  }

  // Caso 1: Dois titulares -> troca as posições entre eles
  if (sourceLineupIdx >= 0 && targetLineupIdx >= 0 && sourceLineupIdx !== targetLineupIdx) {
    [state.lineup[sourceLineupIdx], state.lineup[targetLineupIdx]] = 
      [state.lineup[targetLineupIdx], state.lineup[sourceLineupIdx]];
  }
  // Caso 2: targetLineupIdx é a vaga titular e sKey é reserva -> reserva entra na vaga
  else if (targetLineupIdx >= 0 && sKey) {
    // Garante que sKey não fique duplicado em nenhuma outra posição
    state.lineup = state.lineup.map((k, idx) => (idx !== targetLineupIdx && (k === sKey || (sKey && playerKey(findSquadPlayerByKey(k)) === sKey)) ? null : k));
    if (sourceLineupIdx >= 0) {
      state.lineup[sourceLineupIdx] = state.lineup[targetLineupIdx];
    }
    state.lineup[targetLineupIdx] = sKey;
  }
  // Caso 3: sourceLineupIdx é a vaga titular e tKey é reserva -> reserva entra na vaga
  else if (sourceLineupIdx >= 0 && tKey) {
    state.lineup = state.lineup.map((k, idx) => (idx !== sourceLineupIdx && (k === tKey || (tKey && playerKey(findSquadPlayerByKey(k)) === tKey)) ? null : k));
    if (targetLineupIdx >= 0) {
      state.lineup[targetLineupIdx] = state.lineup[sourceLineupIdx];
    }
    state.lineup[sourceLineupIdx] = tKey;
  }
  // Caso 4: targetSlotIndex válido com um jogador para ocupar a vaga
  else if (Number.isInteger(targetSlotIndex) && targetSlotIndex >= 0 && targetSlotIndex < 11) {
    const keyToInsert = sKey || tKey;
    if (keyToInsert) {
      state.lineup = state.lineup.map((k, idx) => (idx !== targetSlotIndex && (k === keyToInsert || playerKey(findSquadPlayerByKey(k)) === keyToInsert) ? null : k));
      state.lineup[targetSlotIndex] = keyToInsert;
    }
  }
  else {
    return toast('Selecione uma vaga titular para fazer a troca.');
  }

  tacticalSelectedKey = null;
  save();
  render();
  toast('🔄 Escalação atualizada com sucesso!');
}

function setupPitchDragAndDrop(){
  const myTeamContainer = $('#myTeamTacticsContainer');
  if(myTeamContainer){
    const formSlots = formationSlots() || [];
    const startingPlayers = formSlots.map((slot, idx) => {
      const pk = state.lineup?.[idx];
      return pk ? findSquadPlayerByKey(pk) : null;
    });
    const bench = state.squad.filter(p => !(state.lineup||[]).includes(playerKey(p))).sort((a,b)=>playerOverall(b)-playerOverall(a));

    setupTacticsInteractions({
      containerEl: myTeamContainer,
      starters: startingPlayers,
      bench: bench,
      onSwap: (targetKey, benchKey, targetSlotIndex) => {
        executeSwap(benchKey, targetKey, targetSlotIndex, null);
      },
      onStarterSwap: (key1, key2, idx1, idx2) => {
        executeSwap(key1, key2, idx2, idx1);
      },
      isHalftime: false
    });
    return;
  }
}

// -------------------------------------------------------------
// COMPARADOR VISUAL DE JOGADORES LADO A LADO (Melhoria 46)
// -------------------------------------------------------------
function openPlayerCompareModal(key1, key2){
  const pool = state?.squad || [];
  if(pool.length === 0) return toast('Elenco vazio para comparação.');
  const p1 = pool.find(p => playerKey(p) === key1) || pool[0];
  const p2 = pool.find(p => playerKey(p) === key2) || pool[1] || pool[0];

  function buildHtml(pA, pB){
    const ovrA = playerOverall(pA), ovrB = playerOverall(pB);
    const valA = calcValueMi(pA), valB = calcValueMi(pB);
    const wageA = playerSalary(pA), wageB = playerSalary(pB);
    const fitA = pA.fitness ?? 100, fitB = pB.fitness ?? 100;
    const potA = pA.potential || (ovrA + 5), potB = pB.potential || (ovrB + 5);

    function compBar(label, val1, val2, unit=''){
      const max = Math.max(val1, val2, 1);
      const pct1 = Math.round((val1 / max) * 100);
      const pct2 = Math.round((val2 / max) * 100);
      const win1 = val1 > val2, win2 = val2 > val1;
      return `
        <div style="margin:10px 0">
          <div style="display:flex;justify-content:space-between;font-size:12px;font-weight:800;margin-bottom:4px">
            <span style="color:${win1 ? 'var(--neon)' : '#fff'}">${val1}${unit}</span>
            <span style="color:rgba(255,255,255,0.6);text-transform:uppercase;font-size:11px">${label}</span>
            <span style="color:${win2 ? 'var(--cyan)' : '#fff'}">${val2}${unit}</span>
          </div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:4px;height:8px">
            <div style="display:flex;justify-content:flex-end;background:rgba(255,255,255,0.06);border-radius:4px;overflow:hidden">
              <div style="width:${pct1}%;background:${win1 ? 'var(--neon)' : '#64748b'};border-radius:4px"></div>
            </div>
            <div style="display:flex;justify-content:flex-start;background:rgba(255,255,255,0.06);border-radius:4px;overflow:hidden">
              <div style="width:${pct2}%;background:${win2 ? 'var(--cyan)' : '#64748b'};border-radius:4px"></div>
            </div>
          </div>
        </div>
      `;
    }

    return `
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px">
        <div style="background:#16122c;border:2px solid var(--neon);border-radius:14px;padding:16px;text-align:center">
          ${playerPhoto(pA.name, 60)}
          <h3 style="margin:8px 0 2px 0;font-size:16px;color:#fff">${esc(pA.name)}</h3>
          <div class="small" style="color:var(--neon);font-weight:900">${pA.pos} · OVR ${ovrA}</div>
          <select id="selCompPlayerA" class="btn" style="width:100%;margin-top:10px;font-size:11px">
            ${pool.map(p => `<option value="${playerKey(p)}" ${playerKey(p)===playerKey(pA)?'selected':''}>${esc(p.name)} (${p.pos} · ${playerOverall(p)})</option>`).join('')}
          </select>
        </div>

        <div style="background:#16122c;border:2px solid var(--cyan);border-radius:14px;padding:16px;text-align:center">
          ${playerPhoto(pB.name, 60)}
          <h3 style="margin:8px 0 2px 0;font-size:16px;color:#fff">${esc(pB.name)}</h3>
          <div class="small" style="color:var(--cyan);font-weight:900">${pB.pos} · OVR ${ovrB}</div>
          <select id="selCompPlayerB" class="btn" style="width:100%;margin-top:10px;font-size:11px">
            ${pool.map(p => `<option value="${playerKey(p)}" ${playerKey(p)===playerKey(pB)?'selected':''}>${esc(p.name)} (${p.pos} · ${playerOverall(p)})</option>`).join('')}
          </select>
        </div>
      </div>

      <div style="background:#100d1e;border:1px solid rgba(255,255,255,0.08);border-radius:14px;padding:18px">
        ${compBar('Overall (Habilidade)', ovrA, ovrB)}
        ${compBar('Potencial Futuro', potA, potB)}
        ${compBar('Condição Física', fitA, fitB, '%')}
        ${compBar('Idade (Juventude)', 40 - (pA.age||25), 40 - (pB.age||25), ' anos')}
        ${compBar('Valor de Mercado (Mi)', valA, valB, ' Mi')}
        ${compBar('Salário Mensal', Math.round(wageA/1000), Math.round(wageB/1000), 'k')}
      </div>
    `;
  }

  openCustomModal(
    '⚖️ Comparador Oficial de Jogadores (Head-to-Head)',
    `<div id="compareModalBody">${buildHtml(p1, p2)}</div>`,
    null,
    'Fechar',
    false,
    '650px'
  );

  function wireSelects(){
    const selA = $('#selCompPlayerA'), selB = $('#selCompPlayerB');
    if(selA) selA.onchange = () => {
      const curA = pool.find(p => playerKey(p) === selA.value);
      const curB = pool.find(p => playerKey(p) === selB.value);
      const box = $('#compareModalBody');
      if(box && curA && curB){ box.innerHTML = buildHtml(curA, curB); wireSelects(); }
    };
    if(selB) selB.onchange = () => {
      const curA = pool.find(p => playerKey(p) === selA.value);
      const curB = pool.find(p => playerKey(p) === selB.value);
      const box = $('#compareModalBody');
      if(box && curA && curB){ box.innerHTML = buildHtml(curA, curB); wireSelects(); }
    };
  }
  wireSelects();
}

